pub fn module_unit_from_source(
    module_name: impl Into<String>,
    module_kind: ModuleKind,
    source: impl Into<String>,
) -> Result<ModuleUnit, ProjectCompileError> {
    let module_name = module_name.into();
    let source = source.into();
    let mut attrs = ModuleAttributes {
        vb_name: module_name.clone(),
        ..ModuleAttributes::default()
    };
    for line in source.lines() {
        let trimmed = line.trim();
        let lower = trimmed.to_ascii_lowercase();
        if lower.starts_with("attribute ") {
            parse_attribute_line(trimmed, &mut attrs, &module_name)?;
        } else if lower == "option private module" {
            attrs.option_private_module = true;
        }
    }
    let semantic_module_name = attrs.vb_name.clone();

    Ok(ModuleUnit {
        module_name: semantic_module_name,
        module_kind,
        attributes: attrs,
        source,
    })
}

pub fn compile_project(manifest: &ProjectManifest) -> Result<CompiledProject, ProjectCompileError> {
    compile_project_with_strategy(manifest, selected_project_lowering_strategy())
}

fn selected_project_lowering_strategy() -> ProjectLoweringStrategy {
    match std::env::var("OXVBA_PMR_LOWERING")
        .ok()
        .map(|value| value.trim().to_ascii_lowercase())
        .as_deref()
    {
        Some("rewrite-bridge") => ProjectLoweringStrategy::RewriteBridge,
        _ => ProjectLoweringStrategy::ModuleAwareBindPlan,
    }
}

fn compile_project_with_strategy(
    manifest: &ProjectManifest,
    strategy: ProjectLoweringStrategy,
) -> Result<CompiledProject, ProjectCompileError> {
    preflight_typelib_binding_diagnostics(manifest)?;
    validate_manifest(manifest)?;

    // Augment reference_projects with explicit project-shaped imported typelib references.
    let mut augmented_refs = manifest.reference_projects.clone();
    for reference in &manifest.references {
        if reference.reference_kind == ReferenceKind::TypeLibrary
            && let Some(identity) =
                resolve_typelib_identity_for_reference(&reference.referenced_project_name)
        {
            let projected = project_imported_typelib_reference(&identity);
            let key = normalize_identifier(&projected.manifest.project_name);
            if !augmented_refs
                .iter()
                .any(|r| normalize_identifier(&r.project_name) == key)
            {
                augmented_refs.push(projected.manifest);
            }
        }
    }
    let manifest = &ProjectManifest {
        reference_projects: augmented_refs,
        ..manifest.clone()
    };

    let procedure_index = collect_project_procedures(manifest);
    let reference_order = build_reference_order_map(manifest);
    let active_project = normalize_identifier(&manifest.project_name);
    validate_event_semantics(manifest, &procedure_index, &reference_order)?;
    validate_imported_module_scope_declarations(manifest, &reference_order)?;
    validate_imported_procedure_signatures(manifest, &reference_order)?;
    validate_imported_event_declarations(manifest, &reference_order)?;
    let event_dispatch_plan =
        collect_event_dispatch_plan(manifest, &procedure_index, &reference_order)?;

    let (rewritten_source, dynamic_instance_bindings, forced_object_locals_by_proc) =
        lower_project_source(
            strategy,
            manifest,
            &active_project,
            &procedure_index,
            &reference_order,
            &event_dispatch_plan,
        )?;

    let has_class_modules = manifest
        .modules
        .iter()
        .any(|m| matches!(m.module_kind, ModuleKind::Class | ModuleKind::Document));
    let (bytecode, mut procedure_runtime_metadata) =
        compile_with_runtime_metadata_object_locals_class(
            &rewritten_source,
            &forced_object_locals_by_proc,
            has_class_modules,
        )
        .map_err(|e| ProjectCompileError::BackendCompile {
            message: e.to_string(),
        })?;

    let host_exports = collect_host_exports(manifest, &procedure_index);
    let reference_visible_exports = collect_reference_visible_exports(manifest, &procedure_index);
    decorate_project_procedure_runtime_metadata(&mut procedure_runtime_metadata, &procedure_index);
    let event_dispatch_bindings = flatten_event_dispatch_plan(&event_dispatch_plan);
    let project_com_withevents_routes =
        build_project_com_withevents_routes(manifest, &event_dispatch_plan);
    let implements_map =
        collect_class_implements_map(manifest, &procedure_index, &reference_order)?;
    let project_dynamic_objects = build_project_dynamic_object_routes(
        manifest,
        &dynamic_instance_bindings,
        &procedure_index,
        &procedure_runtime_metadata,
        &implements_map,
    );
    validate_compiled_project_contract(manifest, &host_exports, &reference_visible_exports)
        .map_err(|message| ProjectCompileError::BackendCompile {
            message: format!("PMR-E-INTERNAL-CONTRACT: {message}"),
        })?;
    Ok(CompiledProject {
        bytecode,
        procedure_runtime_metadata,
        rewritten_source,
        host_exports,
        reference_visible_exports,
        event_dispatch_bindings,
        project_com_withevents_routes,
        project_dynamic_objects,
    })
}

fn decorate_project_procedure_runtime_metadata(
    runtime_metadata: &mut BTreeMap<String, ProcedureRuntimeMetadata>,
    procedures: &[ProcedureDecl],
) {
    for decl in procedures {
        if let Some(metadata) = runtime_metadata.get_mut(&decl.lowered_name) {
            metadata.module_name = decl.module_name.clone();
            metadata.procedure_name = decl.procedure_name.clone();
        }
    }
}

fn projected_typelib_reference_cache() -> &'static Mutex<BTreeMap<String, ReferencedProjectManifest>>
{
    PROJECTED_TYPELIB_REFERENCE_CACHE.get_or_init(|| Mutex::new(BTreeMap::new()))
}

pub fn project_imported_typelib_reference(
    identity: &TypeLibResolvedIdentity,
) -> ProjectedTypeLibReference {
    let blob = build_typelib_metadata(identity);
    project_imported_typelib_reference_from_blob(&blob)
}

fn project_imported_typelib_reference_from_blob(
    blob: &TypeLibMetadataBlob,
) -> ProjectedTypeLibReference {
    let freshness_key = projected_typelib_freshness_key(blob);
    let cache_lookup_key = format!("{}::{freshness_key}", blob.identity.cache_key);
    let manifest = {
        let mut cache = projected_typelib_reference_cache()
            .lock()
            .expect("projected typelib reference cache lock poisoned");
        if let Some(cached) = cache.get(&cache_lookup_key).cloned() {
            cached
        } else {
            let projected = build_projected_typelib_manifest(blob, &freshness_key);
            cache.insert(cache_lookup_key, projected.clone());
            projected
        }
    };
    ProjectedTypeLibReference {
        identity: blob.identity.clone(),
        freshness_key,
        manifest,
    }
}

fn projected_typelib_freshness_key(blob: &TypeLibMetadataBlob) -> String {
    let mut hasher = DefaultHasher::new();
    blob.identity.reference_name.hash(&mut hasher);
    blob.identity.requested_coclass.hash(&mut hasher);
    blob.identity.importlib.hash(&mut hasher);
    blob.identity.libid.hash(&mut hasher);
    blob.identity.major_version.hash(&mut hasher);
    blob.identity.minor_version.hash(&mut hasher);
    blob.identity.lcid.hash(&mut hasher);
    blob.activation_prog_id.hash(&mut hasher);
    blob.member_name_to_token.hash(&mut hasher);
    for member in &blob.members {
        member.name.hash(&mut hasher);
        member.token.hash(&mut hasher);
        member.requires_argument.hash(&mut hasher);
        typelib_member_invoke_kind_tag(member.invoke_kind).hash(&mut hasher);
        member.parameter_names.hash(&mut hasher);
        member.is_default_member.hash(&mut hasher);
        for parameter_type in &member.parameter_types {
            typelib_param_type_tag(*parameter_type).hash(&mut hasher);
        }
        member
            .return_type
            .map(typelib_param_type_tag)
            .hash(&mut hasher);
    }
    for event in &blob.events {
        event.name.hash(&mut hasher);
        event.token.hash(&mut hasher);
        event.callback_arity.hash(&mut hasher);
        event.connection_point_iid.hash(&mut hasher);
        event.dispatch_member_id.hash(&mut hasher);
        match event.dispatch_path {
            oxvba_com::TypeLibEventDispatchPath::Dispatch => 0_u8,
            oxvba_com::TypeLibEventDispatchPath::SourceInterface => 1_u8,
        }
        .hash(&mut hasher);
    }
    format!("{:016x}", hasher.finish())
}

fn typelib_member_invoke_kind_tag(kind: TypeLibMemberInvokeKind) -> u8 {
    match kind {
        TypeLibMemberInvokeKind::PropertyGet => 0,
        TypeLibMemberInvokeKind::Method => 1,
        TypeLibMemberInvokeKind::PropertyPut => 2,
        TypeLibMemberInvokeKind::PropertyPutRef => 3,
    }
}

fn typelib_param_type_tag(kind: TypeLibParamType) -> u8 {
    match kind {
        TypeLibParamType::Variant => 0,
        TypeLibParamType::Long => 1,
        TypeLibParamType::Integer => 2,
        TypeLibParamType::String => 3,
        TypeLibParamType::Boolean => 4,
        TypeLibParamType::Double => 5,
        TypeLibParamType::Single => 6,
        TypeLibParamType::Currency => 7,
        TypeLibParamType::Date => 8,
        TypeLibParamType::Decimal => 9,
        TypeLibParamType::Object => 10,
        TypeLibParamType::Byte => 11,
        TypeLibParamType::LongLong => 12,
        TypeLibParamType::LongPtr => 13,
        TypeLibParamType::ByRefVariant => 14,
        TypeLibParamType::ByRefLong => 15,
        TypeLibParamType::ByRefInteger => 16,
        TypeLibParamType::ByRefString => 17,
        TypeLibParamType::ByRefDouble => 18,
        TypeLibParamType::ByRefSingle => 19,
        TypeLibParamType::ByRefCurrency => 20,
        TypeLibParamType::ByRefDate => 21,
        TypeLibParamType::ByRefDecimal => 22,
        TypeLibParamType::ByRefObject => 23,
        TypeLibParamType::ByRefByte => 24,
        TypeLibParamType::ByRefBoolean => 25,
        TypeLibParamType::ByRefLongLong => 26,
        TypeLibParamType::ByRefLongPtr => 27,
    }
}

fn preflight_typelib_binding_diagnostics(
    manifest: &ProjectManifest,
) -> Result<(), ProjectCompileError> {
    for project in &manifest.reference_projects {
        let Some(module) = first_typelib_binding_diagnostic_module(project) else {
            continue;
        };
        if project.modules.len() != 1 {
            continue;
        }
        return Err(parse_typelib_binding_diagnostic(module)?);
    }
    Ok(())
}

fn first_typelib_binding_diagnostic_module(
    project: &ReferencedProjectManifest,
) -> Option<&ModuleUnit> {
    project
        .modules
        .iter()
        .find(|module| module.module_name == TYPELIB_BINDING_DIAGNOSTIC_MODULE_NAME)
}

fn referenced_project_typelib_binding_diagnostic(
    project: &ReferencedProjectManifest,
) -> Result<Option<ProjectCompileError>, ProjectCompileError> {
    let Some(module) = first_typelib_binding_diagnostic_module(project) else {
        return Ok(None);
    };
    Ok(Some(parse_typelib_binding_diagnostic(module)?))
}

fn parse_typelib_binding_diagnostic(
    module: &ModuleUnit,
) -> Result<ProjectCompileError, ProjectCompileError> {
    let mut code = None;
    let mut message = None;
    for line in module.source.lines() {
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        match key.trim() {
            "code" => code = Some(value.trim()),
            "message" => message = Some(value.trim()),
            _ => {}
        }
    }
    let code = code.ok_or_else(|| ProjectCompileError::BackendCompile {
        message: "typelib binding diagnostic project is missing `code`".to_string(),
    })?;
    let message = message.ok_or_else(|| ProjectCompileError::BackendCompile {
        message: "typelib binding diagnostic project is missing `message`".to_string(),
    })?;
    let code = match code {
        "PMR-E-TYPELIB-IMPORTLIB-MISSING" => "PMR-E-TYPELIB-IMPORTLIB-MISSING",
        "PMR-E-TYPELIB-IMPORTLIB-UNRESOLVED" => "PMR-E-TYPELIB-IMPORTLIB-UNRESOLVED",
        "PMR-E-TYPELIB-IMPORTLIB-AMBIGUOUS" => "PMR-E-TYPELIB-IMPORTLIB-AMBIGUOUS",
        "PMR-E-TYPELIB-LIBID-UNRESOLVED" => "PMR-E-TYPELIB-LIBID-UNRESOLVED",
        "PMR-E-TYPELIB-LIBID-AMBIGUOUS" => "PMR-E-TYPELIB-LIBID-AMBIGUOUS",
        other => {
            return Err(ProjectCompileError::BackendCompile {
                message: format!("unsupported typelib binding diagnostic code `{other}`"),
            });
        }
    };
    Ok(ProjectCompileError::TypeLibraryBindingFailure {
        code,
        message: message.to_string(),
    })
}

fn lower_project_source(
    strategy: ProjectLoweringStrategy,
    manifest: &ProjectManifest,
    active_project: &str,
    procedures: &[ProcedureDecl],
    reference_order: &BTreeMap<String, usize>,
    event_dispatch_plan: &EventDispatchPlan,
) -> Result<LoweredProjectSource, ProjectCompileError> {
    let mut lowered_modules = Vec::new();
    let mut next_internal_instance_id = 1i32;
    let mut dynamic_instance_bindings = Vec::new();
    let mut forced_object_locals_by_proc = BTreeMap::<String, BTreeSet<String>>::new();
    // Emit procedural modules before class modules so the bytecode entry
    // point (pc=0) lands in a procedural module rather than in a class
    // module helper function.  Within each category, preserve the original
    // module order (which is typically alphabetical from the filesystem).
    let module_order: Vec<usize> = {
        let procedural: Vec<usize> = (0..manifest.modules.len())
            .filter(|&i| manifest.modules[i].module_kind == ModuleKind::Procedural)
            .collect();
        let non_procedural: Vec<usize> = (0..manifest.modules.len())
            .filter(|&i| manifest.modules[i].module_kind != ModuleKind::Procedural)
            .collect();
        procedural.into_iter().chain(non_procedural).collect()
    };
    for &idx in &module_order {
        let module = &manifest.modules[idx];
        let (lowered, object_locals) = lower_module_source(
            strategy,
            manifest,
            active_project,
            module,
            active_project,
            procedures,
            reference_order,
            event_dispatch_plan,
            &mut next_internal_instance_id,
            &mut dynamic_instance_bindings,
        )?;
        lowered_modules.push(lowered);
        merge_forced_object_locals(&mut forced_object_locals_by_proc, object_locals);
    }
    for referenced in ordered_reference_projects(manifest) {
        let project_name = normalize_identifier(&referenced.project_name);
        for module in &referenced.modules {
            if is_typelib_binding_diagnostic_module(module) {
                continue;
            }
            let (lowered, object_locals) = lower_module_source(
                strategy,
                manifest,
                active_project,
                module,
                &project_name,
                procedures,
                reference_order,
                event_dispatch_plan,
                &mut next_internal_instance_id,
                &mut dynamic_instance_bindings,
            )?;
            lowered_modules.push(lowered);
            merge_forced_object_locals(&mut forced_object_locals_by_proc, object_locals);
        }
    }
    Ok((
        lowered_modules.join("\n"),
        dynamic_instance_bindings,
        forced_object_locals_by_proc,
    ))
}

#[allow(clippy::too_many_arguments)]
fn lower_module_source(
    strategy: ProjectLoweringStrategy,
    manifest: &ProjectManifest,
    active_project: &str,
    module: &ModuleUnit,
    current_project: &str,
    procedures: &[ProcedureDecl],
    reference_order: &BTreeMap<String, usize>,
    event_dispatch_plan: &EventDispatchPlan,
    next_internal_instance_id: &mut i32,
    dynamic_instance_bindings: &mut Vec<ProjectDynamicInstanceBindingDraft>,
) -> Result<(String, ForcedObjectLocalsByProc), ProjectCompileError> {
    match strategy {
        ProjectLoweringStrategy::ModuleAwareBindPlan => lower_module_source_module_aware(
            manifest,
            active_project,
            module,
            current_project,
            procedures,
            reference_order,
            event_dispatch_plan,
            next_internal_instance_id,
            dynamic_instance_bindings,
        ),
        ProjectLoweringStrategy::RewriteBridge => rewrite_module_source(
            manifest,
            active_project,
            module,
            current_project,
            procedures,
            reference_order,
            event_dispatch_plan,
            next_internal_instance_id,
            dynamic_instance_bindings,
        ),
    }
}

fn merge_forced_object_locals(
    target: &mut ForcedObjectLocalsByProc,
    source: ForcedObjectLocalsByProc,
) {
    for (proc_name, vars) in source {
        target.entry(proc_name).or_default().extend(vars);
    }
}

fn record_internal_class_object_local(
    forced_object_locals_by_proc: &mut ForcedObjectLocalsByProc,
    active_procedure_name: &Option<String>,
    line: &str,
    manifest: &ProjectManifest,
    current_project: &str,
    reference_order: &BTreeMap<String, usize>,
) -> Result<(), ProjectCompileError> {
    let Some(proc_name) = active_procedure_name else {
        return Ok(());
    };
    if parse_external_dim_declaration(line).is_some() {
        return Ok(());
    }
    let Some(dim_decl) = parse_internal_class_dim_declaration(line) else {
        return Ok(());
    };
    if resolve_interface_module(
        manifest,
        current_project,
        &dim_decl.type_name,
        reference_order,
    )?
    .is_none()
    {
        return Ok(());
    }
    forced_object_locals_by_proc
        .entry(proc_name.clone())
        .or_default()
        .insert(normalize_identifier(&dim_decl.var_name));
    Ok(())
}

fn lowered_procedure_binding_for_line(
    line: &str,
    procedures: &[ProcedureDecl],
    current_project: &str,
    current_module: &str,
) -> Option<String> {
    let normalized = normalize_visibility_prefixed_procedure_signature(line);
    let (proc_name, kind, _) = parse_procedure_signature_line(&normalized)?;
    let decl = find_decl_by_signature(
        procedures,
        current_project,
        current_module,
        &proc_name,
        kind,
    )?;
    Some(decl.lowered_name.clone())
}

fn clear_active_procedure_name_if_end(active_procedure_name: &mut Option<String>, line: &str) {
    let lower = line.trim().to_ascii_lowercase();
    if lower == "end sub" || lower == "end function" || lower == "end property" {
        *active_procedure_name = None;
    }
}

fn validate_manifest(manifest: &ProjectManifest) -> Result<(), ProjectCompileError> {
    if !is_valid_vba_identifier(&manifest.project_name) {
        return Err(ProjectCompileError::ProjectNameInvalid {
            name: manifest.project_name.clone(),
        });
    }
    let mut module_names = BTreeSet::new();
    for module in &manifest.modules {
        if !is_valid_vba_identifier(&module.module_name) {
            return Err(ProjectCompileError::ModuleNameInvalid {
                name: module.module_name.clone(),
            });
        }
        if module.module_name.chars().count() > 31 {
            return Err(ProjectCompileError::ModuleNameLength {
                name: module.module_name.clone(),
            });
        }
        if !module
            .attributes
            .vb_name
            .eq_ignore_ascii_case(&module.module_name)
        {
            return Err(ProjectCompileError::ModuleHeaderVbNameMismatch {
                module_name: module.module_name.clone(),
                vb_name: module.attributes.vb_name.clone(),
            });
        }
        if manifest.project_kind == ProjectKind::Source
            && module.module_kind == ModuleKind::Class
            && (module.attributes.vb_global_namespace || module.attributes.vb_creatable)
        {
            return Err(ProjectCompileError::SourceProjectClassAttributeConstraint);
        }
        if module.attributes.option_private_module && module.module_kind != ModuleKind::Procedural {
            return Err(ProjectCompileError::OptionPrivateModuleKind {
                module_name: module.module_name.clone(),
            });
        }
        if module.module_kind == ModuleKind::Extension && manifest.project_kind != ProjectKind::Host
        {
            return Err(ProjectCompileError::ExtensionModuleProjectKind {
                module_name: module.module_name.clone(),
            });
        }
        let key = normalize_identifier(&module.module_name);
        if !module_names.insert(key) {
            return Err(ProjectCompileError::ModuleNameDuplicate {
                name: module.module_name.clone(),
            });
        }
    }

    let mut refs = BTreeSet::new();
    for reference in &manifest.references {
        if !is_valid_vba_identifier(&reference.referenced_project_name) {
            return Err(ProjectCompileError::ReferenceNameInvalid {
                name: reference.referenced_project_name.clone(),
            });
        }
        let key = normalize_identifier(&reference.referenced_project_name);
        if !refs.insert(key) {
            return Err(ProjectCompileError::ReferenceDuplicateTarget {
                name: reference.referenced_project_name.clone(),
            });
        }
    }

    let mut ref_projects = BTreeSet::new();
    for referenced in &manifest.reference_projects {
        if !is_valid_vba_identifier(&referenced.project_name) {
            return Err(ProjectCompileError::ReferenceNameInvalid {
                name: referenced.project_name.clone(),
            });
        }
        let key = normalize_identifier(&referenced.project_name);
        if !refs.contains(&key) && !is_synthetic_typelib_reference_project(referenced) {
            return Err(ProjectCompileError::ReferenceProjectNotDeclared {
                name: referenced.project_name.clone(),
            });
        }
        if !ref_projects.insert(key) {
            return Err(ProjectCompileError::ReferenceProjectDuplicate {
                name: referenced.project_name.clone(),
            });
        }
        validate_modules_for_project(
            &referenced.project_name,
            ProjectKind::Library,
            &referenced.modules,
        )?;
    }

    Ok(())
}

fn is_synthetic_typelib_reference_project(project: &ReferencedProjectManifest) -> bool {
    projected_typelib_reference_provenance(project).is_some()
}

fn projected_typelib_reference_provenance(
    project: &ReferencedProjectManifest,
) -> Option<ProjectedTypeLibReferenceProvenance> {
    let values = project
        .modules
        .iter()
        .filter(|module| module.module_kind == ModuleKind::Class)
        .find_map(parse_projected_typelib_reference_module_provenance)?;
    Some(ProjectedTypeLibReferenceProvenance {
        identity: TypeLibResolvedIdentity {
            reference_name: values.get("reference-name")?.clone(),
            requested_coclass: non_empty_owned(values.get("requested-coclass")?.clone()),
            importlib: values.get("importlib")?.clone(),
            libid: non_empty_owned(values.get("libid")?.clone()),
            major_version: values.get("major-version")?.parse().ok()?,
            minor_version: values.get("minor-version")?.parse().ok()?,
            lcid: non_empty_owned(values.get("lcid")?.clone()).and_then(|value| value.parse().ok()),
            cache_key: values.get("cache-key")?.clone(),
        },
        freshness_key: values.get("freshness-key")?.clone(),
    })
}

fn parse_projected_typelib_reference_module_provenance(
    module: &ModuleUnit,
) -> Option<BTreeMap<String, String>> {
    let mut found_marker = false;
    let mut values = BTreeMap::new();
    for line in module.source.lines() {
        let trimmed = line.trim();
        if trimmed == PROJECTED_TYPELIB_REFERENCE_MARKER {
            found_marker = true;
            continue;
        }
        let Some(rest) = trimmed.strip_prefix(PROJECTED_TYPELIB_REFERENCE_PREFIX) else {
            continue;
        };
        let (key, value) = rest.split_once('=')?;
        values.insert(key.to_string(), value.to_string());
    }
    found_marker.then_some(values)
}

fn non_empty_owned(value: String) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn is_typelib_binding_diagnostic_module(module: &ModuleUnit) -> bool {
    module.module_name == TYPELIB_BINDING_DIAGNOSTIC_MODULE_NAME
}

fn validate_event_semantics(
    manifest: &ProjectManifest,
    procedures: &[ProcedureDecl],
    reference_order: &BTreeMap<String, usize>,
) -> Result<(), ProjectCompileError> {
    let mut class_public_members = BTreeMap::<(String, String), BTreeSet<String>>::new();
    let mut class_declared_events = BTreeMap::<(String, String), BTreeSet<String>>::new();

    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        let project_key = normalize_identifier(project_name);
        let module_key = normalize_identifier(&module.module_name);
        let events = collect_declared_events(module);
        if !events.is_empty() {
            class_declared_events.insert((project_key.clone(), module_key.clone()), events);
        }
    }

    for decl in procedures {
        if decl.module_kind == ModuleKind::Class && decl.is_public {
            class_public_members
                .entry((decl.project_name.clone(), decl.module_name.clone()))
                .or_default()
                .insert(decl.procedure_name.clone());
        }
    }

    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        let project_key = normalize_identifier(project_name);
        let module_key = normalize_identifier(&module.module_name);
        let module_name = format!("{project_name}.{}", module.module_name);
        for line in module.source.lines() {
            if parse_withevents_declaration(line).is_some()
                && !matches!(
                    module.module_kind,
                    ModuleKind::Class | ModuleKind::Document | ModuleKind::Form
                )
            {
                return Err(ProjectCompileError::WithEventsModuleKind {
                    module_name: module_name.clone(),
                });
            }

            if let Some(interface_target) = parse_implements_target(line) {
                if module.module_kind != ModuleKind::Class {
                    return Err(ProjectCompileError::ImplementsModuleKind {
                        module_name: module_name.clone(),
                    });
                }

                let Some(interface_name) = normalize_procedure_name(&interface_target) else {
                    if is_referenced_typelib_type_reference(manifest, &interface_target) {
                        // Phase 3B: Imported typelib Implements targets are
                        // accepted without member-contract validation; deferred
                        // to runtime.
                        continue;
                    }
                    return Err(ProjectCompileError::ImplementsInterfaceNotFound {
                        module_name: module_name.clone(),
                        interface_name: interface_target,
                    });
                };

                let Some((iface_project, iface_module)) = resolve_interface_module(
                    manifest,
                    &project_key,
                    &interface_name,
                    reference_order,
                )?
                else {
                    if is_referenced_typelib_type_reference(manifest, &interface_target) {
                        // Phase 3B: Imported typelib Implements targets are
                        // accepted without member-contract validation; deferred
                        // to runtime.
                        continue;
                    }
                    return Err(ProjectCompileError::ImplementsInterfaceNotFound {
                        module_name: module_name.clone(),
                        interface_name,
                    });
                };

                let required_members = class_public_members
                    .get(&(iface_project.clone(), iface_module.clone()))
                    .cloned()
                    .unwrap_or_default();
                if required_members.is_empty() {
                    continue;
                }
                let implemented_members = procedures
                    .iter()
                    .filter(|decl| {
                        decl.project_name == project_key
                            && decl.module_name == module_key
                            && decl.module_kind == ModuleKind::Class
                    })
                    .map(|decl| decl.procedure_name.clone())
                    .collect::<BTreeSet<_>>();
                let iface_prefix = normalize_identifier(&interface_name);
                for member in required_members {
                    let expected = format!("{iface_prefix}_{member}");
                    if !implemented_members.contains(&expected) {
                        return Err(ProjectCompileError::ImplementsMemberMissing {
                            module_name: module_name.clone(),
                            interface_name: iface_prefix.clone(),
                            member_name: member,
                        });
                    }
                }
            }

            if let Some(event_name) = parse_raiseevent_name(line) {
                if module.module_kind != ModuleKind::Class {
                    return Err(ProjectCompileError::RaiseEventModuleKind {
                        module_name: module_name.clone(),
                    });
                }
                let key = (project_key.clone(), module_key.clone());
                let declared = class_declared_events.get(&key).cloned().unwrap_or_default();
                if !declared.contains(&event_name) {
                    return Err(ProjectCompileError::RaiseEventUndeclared {
                        module_name: module_name.clone(),
                        event_name,
                    });
                }
            }
        }
    }

    Ok(())
}

fn validate_imported_module_scope_declarations(
    manifest: &ProjectManifest,
    reference_order: &BTreeMap<String, usize>,
) -> Result<(), ProjectCompileError> {
    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        let project_key = normalize_identifier(project_name);
        let mut in_procedure = false;
        for line in module.source.lines() {
            let normalized = normalize_visibility_prefixed_procedure_signature(line);
            if parse_procedure_signature_line(&normalized).is_some() {
                in_procedure = true;
                continue;
            }
            let lower = line.trim().to_ascii_lowercase();
            if lower == "end sub" || lower == "end function" || lower == "end property" {
                in_procedure = false;
                continue;
            }
            if in_procedure {
                continue;
            }
            for type_name in parse_module_scope_typed_declaration_types(line) {
                if resolve_interface_module(manifest, &project_key, &type_name, reference_order)?
                    .is_some()
                {
                    continue;
                }
                if is_referenced_typelib_type_reference(manifest, &type_name) {
                    // Phase 3C: Imported typelib types in module-scope
                    // declarations fall through; the type resolves as Object.
                    continue;
                }
            }
        }
    }

    Ok(())
}

fn validate_imported_procedure_signatures(
    manifest: &ProjectManifest,
    reference_order: &BTreeMap<String, usize>,
) -> Result<(), ProjectCompileError> {
    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        let project_key = normalize_identifier(project_name);
        for line in module.source.lines() {
            let normalized = normalize_visibility_prefixed_procedure_signature(line);
            if parse_procedure_signature_line(&normalized).is_none() {
                continue;
            }
            for type_name in parse_procedure_signature_type_references(&normalized) {
                if resolve_interface_module(manifest, &project_key, &type_name, reference_order)?
                    .is_some()
                {
                    continue;
                }
                if is_referenced_typelib_type_reference(manifest, &type_name) {
                    // Phase 3D: Imported typelib types in procedure signatures
                    // are treated as Object and compilation proceeds.
                    continue;
                }
            }
        }
    }

    Ok(())
}

fn validate_imported_event_declarations(
    manifest: &ProjectManifest,
    reference_order: &BTreeMap<String, usize>,
) -> Result<(), ProjectCompileError> {
    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        let project_key = normalize_identifier(project_name);
        for line in module.source.lines() {
            for type_name in parse_event_declaration_type_references(line) {
                if resolve_interface_module(manifest, &project_key, &type_name, reference_order)?
                    .is_some()
                {
                    continue;
                }
                if is_referenced_typelib_type_reference(manifest, &type_name) {
                    // Phase 3 (event declarations): Imported typelib types in
                    // Event declarations fall through without error.
                    continue;
                }
            }
        }
    }

    Ok(())
}

fn iter_all_modules<'a>(
    manifest: &'a ProjectManifest,
    reference_order: &'a BTreeMap<String, usize>,
) -> Vec<(&'a str, &'a ModuleUnit)> {
    let mut out = Vec::new();
    out.extend(
        manifest
            .modules
            .iter()
            .map(|module| (manifest.project_name.as_str(), module)),
    );

    let mut referenced = manifest.reference_projects.iter().collect::<Vec<_>>();
    referenced.sort_by_key(|entry| {
        reference_order
            .get(&normalize_identifier(&entry.project_name))
            .copied()
            .unwrap_or(usize::MAX)
    });
    for entry in referenced {
        out.extend(
            entry
                .modules
                .iter()
                .filter(|module| !is_typelib_binding_diagnostic_module(module))
                .map(|module| (entry.project_name.as_str(), module)),
        );
    }
    out
}

fn resolve_interface_module(
    manifest: &ProjectManifest,
    current_project: &str,
    interface_name: &str,
    reference_order: &BTreeMap<String, usize>,
) -> Result<Option<(String, String)>, ProjectCompileError> {
    let iface = normalize_identifier(interface_name);
    for module in &manifest.modules {
        if module.module_kind == ModuleKind::Class
            && normalize_identifier(&module.module_name) == iface
            && normalize_identifier(&manifest.project_name) == current_project
        {
            return Ok(Some((
                normalize_identifier(&manifest.project_name),
                normalize_identifier(&module.module_name),
            )));
        }
    }

    let mut referenced = manifest.reference_projects.iter().collect::<Vec<_>>();
    referenced.sort_by_key(|entry| {
        let normalized_project_name = normalize_identifier(&entry.project_name);
        (
            reference_kind_resolution_priority(manifest, &normalized_project_name),
            reference_order
                .get(&normalized_project_name)
                .copied()
                .unwrap_or(usize::MAX),
        )
    });
    for entry in referenced {
        for module in &entry.modules {
            if module.module_kind == ModuleKind::Class
                && normalize_identifier(&module.module_name) == iface
            {
                if let Some(err) = referenced_project_typelib_binding_diagnostic(entry)? {
                    return Err(err);
                }
                return Ok(Some((
                    normalize_identifier(&entry.project_name),
                    normalize_identifier(&module.module_name),
                )));
            }
        }
    }

    Ok(None)
}

fn reference_kind_resolution_priority(manifest: &ProjectManifest, project_name: &str) -> usize {
    manifest
        .references
        .iter()
        .find(|reference| normalize_identifier(&reference.referenced_project_name) == project_name)
        .map(|reference| match reference.reference_kind {
            ReferenceKind::HostInjected => 0,
            ReferenceKind::Project => 1,
            ReferenceKind::TypeLibrary => 2,
        })
        .unwrap_or(usize::MAX)
}

fn collect_declared_events(module: &ModuleUnit) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for line in module.source.lines() {
        if let Some(name) = parse_event_declaration(line) {
            out.insert(name);
        }
    }
    out
}

fn parse_implements_target(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("implements ") {
        return None;
    }
    let rest = trimmed[11..].trim();
    if rest.is_empty() {
        None
    } else {
        Some(rest.to_string())
    }
}

/// Collect, for each class module, which interfaces it `Implements` and what public members
/// each interface declares. Returns a map from `(project_name, module_name)` to a vec of
/// `(interface_name, vec_of_interface_member_names)`.
type ClassImplementsEntry = Vec<(String, Vec<String>)>;
type ClassImplementsMap = BTreeMap<(String, String), ClassImplementsEntry>;

fn collect_class_implements_map(
    manifest: &ProjectManifest,
    procedures: &[ProcedureDecl],
    reference_order: &BTreeMap<String, usize>,
) -> Result<ClassImplementsMap, ProjectCompileError> {
    // Collect public members of all class modules (mirrors validate_event_semantics).
    let mut class_public_members = BTreeMap::<(String, String), BTreeSet<String>>::new();
    for decl in procedures {
        if decl.module_kind == ModuleKind::Class && decl.is_public {
            class_public_members
                .entry((decl.project_name.clone(), decl.module_name.clone()))
                .or_default()
                .insert(decl.procedure_name.clone());
        }
    }

    let mut result = BTreeMap::new();

    for (project_name, module) in iter_all_modules(manifest, reference_order) {
        if module.module_kind != ModuleKind::Class {
            continue;
        }
        let project_key = normalize_identifier(project_name);
        let module_key = normalize_identifier(&module.module_name);

        let mut interfaces = Vec::new();
        for line in module.source.lines() {
            if let Some(interface_target) = parse_implements_target(line) {
                let Some(interface_name) = normalize_procedure_name(&interface_target) else {
                    continue;
                };
                let Some((iface_project, iface_module)) = resolve_interface_module(
                    manifest,
                    &project_key,
                    &interface_name,
                    reference_order,
                )?
                else {
                    continue;
                };
                let members: Vec<String> = class_public_members
                    .get(&(iface_project, iface_module))
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .collect();
                interfaces.push((normalize_identifier(&interface_name), members));
            }
        }
        if !interfaces.is_empty() {
            result.insert((project_key, module_key), interfaces);
        }
    }

    Ok(result)
}

fn parse_event_declaration(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    let payload = if lower.starts_with("event ") {
        trimmed[6..].trim()
    } else if lower.starts_with("public event ") {
        trimmed[13..].trim()
    } else if lower.starts_with("private event ") {
        trimmed[14..].trim()
    } else {
        return None;
    };
    let token = payload
        .split(|ch: char| ch.is_ascii_whitespace() || ch == '(')
        .next()
        .unwrap_or_default();
    normalize_procedure_name(token)
}

fn parse_event_declaration_type_references(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    let payload = if lower.starts_with("event ") {
        trimmed[6..].trim()
    } else if lower.starts_with("public event ") {
        trimmed[13..].trim()
    } else if lower.starts_with("private event ") {
        trimmed[14..].trim()
    } else {
        return Vec::new();
    };
    let Some(open_idx) = payload.find('(') else {
        return Vec::new();
    };
    let Some(close_idx) = find_matching_paren(payload, open_idx) else {
        return Vec::new();
    };
    let args_raw = payload[open_idx + 1..close_idx].trim();
    let Ok(args) = split_top_level_args(args_raw) else {
        return Vec::new();
    };
    args.into_iter()
        .filter_map(|arg| {
            let (_, rhs) = split_keyword_ascii_ci(arg.trim(), " as ")?;
            extract_signature_type_name(rhs)
        })
        .collect()
}

fn parse_withevents_declaration(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    let payload = if lower.starts_with("dim withevents ") {
        trimmed[15..].trim()
    } else if lower.starts_with("public withevents ") {
        trimmed[18..].trim()
    } else if lower.starts_with("private withevents ") {
        trimmed[19..].trim()
    } else {
        return None;
    };
    let token = payload
        .split(|ch: char| ch.is_ascii_whitespace() || ch == ',' || ch == '(')
        .next()
        .unwrap_or_default();
    normalize_procedure_name(token)
}

fn parse_raiseevent_name(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("raiseevent ") {
        return None;
    }
    let payload = trimmed[10..].trim();
    let token = payload
        .split(|ch: char| ch.is_ascii_whitespace() || ch == '(')
        .next()
        .unwrap_or_default();
    normalize_procedure_name(token)
}

fn collect_project_procedures(manifest: &ProjectManifest) -> Vec<ProcedureDecl> {
    let mut procedures = Vec::new();
    let active_project = normalize_identifier(&manifest.project_name);
    let reference_order = build_reference_order_map(manifest);
    for module in &manifest.modules {
        let module_name = normalize_identifier(&module.module_name);
        let member_attributes = collect_member_attributes(&module.source);
        for line in module.source.lines() {
            if let Some((name, kind, is_public)) = parse_procedure_signature_line(line) {
                let params = procedure_signature_params(line).unwrap_or_default();
                let param_count = params.len();
                let lowered_name = lowered_proc_symbol(&active_project, &module_name, &name, kind);
                procedures.push(ProcedureDecl {
                    project_name: active_project.clone(),
                    module_name: module_name.clone(),
                    procedure_name: name.clone(),
                    lowered_name,
                    kind,
                    is_public,
                    dispatch_id: member_attributes
                        .get(&name)
                        .and_then(|attrs| attrs.vb_user_mem_id),
                    member_flags: member_attributes
                        .get(&name)
                        .and_then(|attrs| attrs.vb_member_flags),
                    is_default_member: member_attributes
                        .get(&name)
                        .is_some_and(|attrs| attrs.vb_user_mem_id == Some(0)),
                    params,
                    param_count,
                    module_kind: module.module_kind,
                    option_private_module: module.attributes.option_private_module,
                    reference_kind: None,
                    implicit_receiver: module.module_kind == ModuleKind::Class,
                    implicit_receiver_precedence: 0,
                });
            }
        }
    }
    for referenced in &manifest.reference_projects {
        let project_name = normalize_identifier(&referenced.project_name);
        let reference_kind = manifest
            .references
            .iter()
            .find(|reference| {
                normalize_identifier(&reference.referenced_project_name) == project_name
            })
            .map(|reference| reference.reference_kind)
            .unwrap_or(ReferenceKind::Project);
        let implicit_receiver_precedence = reference_order
            .get(&project_name)
            .copied()
            .unwrap_or(usize::MAX - 1)
            .saturating_add(1);
        for module in &referenced.modules {
            if is_typelib_binding_diagnostic_module(module) {
                continue;
            }
            let module_name = normalize_identifier(&module.module_name);
            let member_attributes = collect_member_attributes(&module.source);
            for line in module.source.lines() {
                if let Some((name, kind, is_public)) = parse_procedure_signature_line(line) {
                    let params = procedure_signature_params(line).unwrap_or_default();
                    let param_count = params.len();
                    let lowered_name =
                        lowered_proc_symbol(&project_name, &module_name, &name, kind);
                    procedures.push(ProcedureDecl {
                        project_name: project_name.clone(),
                        module_name: module_name.clone(),
                        procedure_name: name.clone(),
                        lowered_name,
                        kind,
                        is_public,
                        dispatch_id: member_attributes
                            .get(&name)
                            .and_then(|attrs| attrs.vb_user_mem_id),
                        member_flags: member_attributes
                            .get(&name)
                            .and_then(|attrs| attrs.vb_member_flags),
                        is_default_member: member_attributes
                            .get(&name)
                            .is_some_and(|attrs| attrs.vb_user_mem_id == Some(0)),
                        params,
                        param_count,
                        module_kind: module.module_kind,
                        option_private_module: module.attributes.option_private_module,
                        reference_kind: Some(reference_kind),
                        implicit_receiver: reference_kind == ReferenceKind::HostInjected
                            && module.module_kind == ModuleKind::Class
                            && (module.attributes.vb_predeclared_id
                                || module.attributes.vb_global_namespace),
                        implicit_receiver_precedence,
                    });
                }
            }
        }
    }
    procedures
}

fn resolve_implicit_class_receiver_binding(
    receiver: &str,
    procedures: &[ProcedureDecl],
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<Option<(String, String, String)>, ProjectCompileError> {
    if shadowed_identifiers.contains(receiver) {
        return Ok(None);
    }
    let mut candidates = procedures
        .iter()
        .filter(|decl| decl.module_name == receiver && decl.implicit_receiver)
        .map(|decl| {
            (
                decl.implicit_receiver_precedence,
                decl.project_name.clone(),
                decl.module_name.clone(),
            )
        })
        .collect::<Vec<_>>();
    candidates.sort();
    candidates.dedup();
    if let Some((_, project_name, module_name)) = candidates.into_iter().next() {
        return Ok(Some((project_name, module_name, "0".to_string())));
    }
    if procedures.iter().any(|decl| {
        decl.module_name == receiver
            && decl.module_kind == ModuleKind::Class
            && decl.reference_kind == Some(ReferenceKind::HostInjected)
    }) {
        return Err(ProjectCompileError::HostRootNotExposed {
            name: receiver.to_string(),
        });
    }
    Ok(None)
}

fn has_implicit_class_receivers(procedures: &[ProcedureDecl]) -> bool {
    procedures.iter().any(|decl| {
        decl.implicit_receiver
            || (decl.module_kind == ModuleKind::Class
                && decl.reference_kind == Some(ReferenceKind::HostInjected))
    })
}

fn parse_declared_identifier_names(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    if trimmed.is_empty() || trimmed.starts_with('\'') {
        return Vec::new();
    }
    let lower = trimmed.to_ascii_lowercase();
    let mut tail = if lower.starts_with("dim ") {
        trimmed[4..].trim_start()
    } else if lower.starts_with("static ") {
        trimmed[7..].trim_start()
    } else if lower.starts_with("private ") {
        trimmed[8..].trim_start()
    } else if lower.starts_with("public ") {
        trimmed[7..].trim_start()
    } else if lower.starts_with("const ") {
        trimmed[6..].trim_start()
    } else {
        return Vec::new();
    };
    let lower_tail = tail.to_ascii_lowercase();
    if lower_tail.starts_with("sub ")
        || lower_tail.starts_with("function ")
        || lower_tail.starts_with("property ")
        || lower_tail.starts_with("event ")
        || lower_tail.starts_with("declare ")
        || lower_tail.starts_with("enum ")
        || lower_tail.starts_with("type ")
        || lower_tail.starts_with("implements ")
    {
        return Vec::new();
    }
    if lower_tail.starts_with("withevents ") {
        tail = tail[11..].trim_start();
    }
    let Ok(parts) = split_top_level_args(tail) else {
        return Vec::new();
    };
    parts
        .into_iter()
        .filter_map(|part| {
            let token = part
                .trim()
                .split(|ch: char| ch.is_ascii_whitespace() || ch == '(' || ch == '=' || ch == ':')
                .next()
                .unwrap_or_default();
            normalize_procedure_name(token)
        })
        .collect()
}

fn parse_signature_parameter_names(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    let Some(open_idx) = trimmed.find('(') else {
        return Vec::new();
    };
    let Some(close_idx) = find_matching_paren(trimmed, open_idx) else {
        return Vec::new();
    };
    let payload = trimmed[open_idx + 1..close_idx].trim();
    if payload.is_empty() {
        return Vec::new();
    }
    let Ok(parts) = split_top_level_args(payload) else {
        return Vec::new();
    };
    parts
        .into_iter()
        .filter_map(|part| {
            let mut remainder = part.trim();
            loop {
                let lower = remainder.to_ascii_lowercase();
                if lower.starts_with("optional ") {
                    remainder = remainder[9..].trim_start();
                } else if lower.starts_with("byval ") || lower.starts_with("byref ") {
                    remainder = remainder[6..].trim_start();
                } else if lower.starts_with("paramarray ") {
                    remainder = remainder[11..].trim_start();
                } else {
                    break;
                }
            }
            let token = remainder
                .split(|ch: char| ch.is_ascii_whitespace() || ch == '(' || ch == '=' || ch == ':')
                .next()
                .unwrap_or_default();
            normalize_procedure_name(token)
        })
        .collect()
}

fn collect_module_shadowed_identifiers(
    module: &ModuleUnit,
) -> (BTreeSet<String>, BTreeMap<String, BTreeSet<String>>) {
    let mut module_shadowed = BTreeSet::new();
    let mut shadowed_by_proc = BTreeMap::<String, BTreeSet<String>>::new();
    let mut active_procedure_name: Option<String> = None;
    for line in module_source_lines_with_class_terminate_cleanup(module) {
        let normalized = normalize_visibility_prefixed_procedure_signature(&line);
        if let Some((proc_name, _, _)) = parse_procedure_signature_line(&normalized) {
            let entry = shadowed_by_proc.entry(proc_name.clone()).or_default();
            entry.insert(proc_name.clone());
            entry.extend(parse_signature_parameter_names(&normalized));
            active_procedure_name = Some(proc_name);
            continue;
        }
        let lower = normalized.trim().to_ascii_lowercase();
        if lower == "end sub" || lower == "end function" || lower == "end property" {
            active_procedure_name = None;
            continue;
        }
        let declared = parse_declared_identifier_names(&line);
        if declared.is_empty() {
            continue;
        }
        if let Some(proc_name) = &active_procedure_name {
            shadowed_by_proc
                .entry(proc_name.clone())
                .or_default()
                .extend(declared);
        } else {
            module_shadowed.extend(declared);
        }
    }
    (module_shadowed, shadowed_by_proc)
}

fn visible_shadowed_identifiers(
    module_shadowed: &BTreeSet<String>,
    shadowed_by_proc: &BTreeMap<String, BTreeSet<String>>,
    procedures: &[ProcedureDecl],
    current_project: &str,
    current_module: &str,
    active_procedure_name: Option<&str>,
) -> BTreeSet<String> {
    let mut visible = module_shadowed.clone();
    if let Some(proc_name) = active_procedure_name {
        if let Some(proc_shadowed) = shadowed_by_proc.get(proc_name) {
            visible.extend(proc_shadowed.iter().cloned());
        } else if let Some(proc_shadowed) = procedures
            .iter()
            .find(|decl| {
                decl.project_name.eq_ignore_ascii_case(current_project)
                    && decl.module_name.eq_ignore_ascii_case(current_module)
                    && decl.lowered_name.eq_ignore_ascii_case(proc_name)
            })
            .and_then(|decl| shadowed_by_proc.get(&normalize_identifier(&decl.procedure_name)))
        {
            visible.extend(proc_shadowed.iter().cloned());
        }
    }
    visible
}

fn validate_modules_for_project(
    project_name: &str,
    project_kind: ProjectKind,
    modules: &[ModuleUnit],
) -> Result<(), ProjectCompileError> {
    let mut module_names = BTreeSet::new();
    for module in modules {
        if !is_valid_vba_identifier(&module.module_name) {
            return Err(ProjectCompileError::ModuleNameInvalid {
                name: module.module_name.clone(),
            });
        }
        if module.module_name.chars().count() > 31 {
            return Err(ProjectCompileError::ModuleNameLength {
                name: module.module_name.clone(),
            });
        }
        if !module
            .attributes
            .vb_name
            .eq_ignore_ascii_case(&module.module_name)
        {
            return Err(ProjectCompileError::ModuleHeaderVbNameMismatch {
                module_name: module.module_name.clone(),
                vb_name: module.attributes.vb_name.clone(),
            });
        }
        if project_kind == ProjectKind::Source
            && module.module_kind == ModuleKind::Class
            && (module.attributes.vb_global_namespace || module.attributes.vb_creatable)
        {
            return Err(ProjectCompileError::SourceProjectClassAttributeConstraint);
        }
        if module.attributes.option_private_module && module.module_kind != ModuleKind::Procedural {
            return Err(ProjectCompileError::OptionPrivateModuleKind {
                module_name: format!("{project_name}.{}", module.module_name),
            });
        }
        if module.module_kind == ModuleKind::Extension && project_kind != ProjectKind::Host {
            return Err(ProjectCompileError::ExtensionModuleProjectKind {
                module_name: format!("{project_name}.{}", module.module_name),
            });
        }
        let key = normalize_identifier(&module.module_name);
        if !module_names.insert(key) {
            return Err(ProjectCompileError::ModuleNameDuplicate {
                name: module.module_name.clone(),
            });
        }
    }
    Ok(())
}

/// Project a `TypeLibMetadataBlob` as a project-shaped imported `ReferencedProjectManifest`.
///
/// The generated module stays explicit about its typelib origin through embedded
/// provenance comments so later compiler passes can rehydrate the imported
/// typelib identity without guessing from project/module names.
pub fn project_typelib_as_manifest(blob: &TypeLibMetadataBlob) -> ReferencedProjectManifest {
    project_imported_typelib_reference_from_blob(blob).manifest
}

fn build_projected_typelib_manifest(
    blob: &TypeLibMetadataBlob,
    freshness_key: &str,
) -> ReferencedProjectManifest {
    let (project_name, module_name) = projected_typelib_manifest_names(blob);

    let mut source_lines = Vec::new();
    source_lines.push(format!("Attribute VB_Name = \"{}\"", module_name));
    source_lines.extend(projected_typelib_reference_comment_lines(
        blob,
        &module_name,
        freshness_key,
    ));
    source_lines.push("' Project-shaped imported COM typelib reference".to_string());

    for member in &blob.members {
        let decl = match member.invoke_kind {
            TypeLibMemberInvokeKind::Method => {
                if member.return_type.is_some() {
                    format!(
                        "Public Function {}({}) As Variant",
                        member.name,
                        build_param_list(&member.parameter_names)
                    )
                } else {
                    format!(
                        "Public Sub {}({})",
                        member.name,
                        build_param_list(&member.parameter_names)
                    )
                }
            }
            TypeLibMemberInvokeKind::PropertyGet => {
                format!(
                    "Public Property Get {}({}) As Variant",
                    member.name,
                    build_param_list(&member.parameter_names)
                )
            }
            TypeLibMemberInvokeKind::PropertyPut | TypeLibMemberInvokeKind::PropertyPutRef => {
                format!(
                    "Public Property Let {}({})",
                    member.name,
                    build_param_list_with_value(&member.parameter_names)
                )
            }
        };
        source_lines.push(decl.clone());
        // Stub body with End
        let end_keyword = match member.invoke_kind {
            TypeLibMemberInvokeKind::Method if member.return_type.is_some() => "End Function",
            TypeLibMemberInvokeKind::Method => "End Sub",
            TypeLibMemberInvokeKind::PropertyGet => "End Property",
            TypeLibMemberInvokeKind::PropertyPut | TypeLibMemberInvokeKind::PropertyPutRef => {
                "End Property"
            }
        };
        source_lines.push(end_keyword.to_string());
    }

    let class_source = source_lines.join("\n");
    let class_module = ModuleUnit {
        module_name: module_name.clone(),
        module_kind: ModuleKind::Class,
        attributes: ModuleAttributes {
            vb_name: module_name.clone(),
            ..ModuleAttributes::default()
        },
        source: class_source,
    };

    for event in &blob.events {
        source_lines.push(format!(
            "Public Event {}({})",
            event.name,
            build_event_param_list(event.callback_arity)
        ));
    }

    ReferencedProjectManifest {
        project_name,
        modules: vec![ModuleUnit {
            source: source_lines.join("\n"),
            ..class_module
        }],
    }
}

fn projected_typelib_reference_comment_lines(
    blob: &TypeLibMetadataBlob,
    module_name: &str,
    freshness_key: &str,
) -> Vec<String> {
    let requested_coclass = blob
        .identity
        .requested_coclass
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(module_name);
    vec![
        PROJECTED_TYPELIB_REFERENCE_MARKER.to_string(),
        projected_typelib_reference_comment("reference-name", &blob.identity.reference_name),
        projected_typelib_reference_comment("requested-coclass", requested_coclass),
        projected_typelib_reference_comment("importlib", &blob.identity.importlib),
        projected_typelib_reference_comment(
            "libid",
            blob.identity.libid.as_deref().unwrap_or_default(),
        ),
        projected_typelib_reference_comment(
            "major-version",
            &blob.identity.major_version.to_string(),
        ),
        projected_typelib_reference_comment(
            "minor-version",
            &blob.identity.minor_version.to_string(),
        ),
        projected_typelib_reference_comment(
            "lcid",
            &blob
                .identity
                .lcid
                .map(|value| value.to_string())
                .unwrap_or_default(),
        ),
        projected_typelib_reference_comment("cache-key", &blob.identity.cache_key),
        projected_typelib_reference_comment("freshness-key", freshness_key),
    ]
}

fn projected_typelib_reference_comment(key: &str, value: &str) -> String {
    format!("{PROJECTED_TYPELIB_REFERENCE_PREFIX}{key}={value}")
}

fn projected_typelib_manifest_names(blob: &TypeLibMetadataBlob) -> (String, String) {
    if let Some(module_name) = blob
        .identity
        .requested_coclass
        .as_deref()
        .filter(|module_name| !module_name.trim().is_empty())
    {
        return (
            blob.identity.reference_name.clone(),
            module_name.to_string(),
        );
    }
    if let Some(module_name) = blob
        .activation_prog_id
        .as_deref()
        .and_then(|prog_id| prog_id.rsplit('.').next())
        .filter(|module_name| !module_name.is_empty())
    {
        return (
            blob.identity.reference_name.clone(),
            module_name.to_string(),
        );
    }
    (
        blob.identity.reference_name.clone(),
        blob.identity.reference_name.clone(),
    )
}

fn build_param_list(params: &[String]) -> String {
    params
        .iter()
        .map(|p| format!("ByVal {} As Variant", p))
        .collect::<Vec<_>>()
        .join(", ")
}

fn build_param_list_with_value(params: &[String]) -> String {
    let mut parts: Vec<String> = params
        .iter()
        .map(|p| format!("ByVal {} As Variant", p))
        .collect();
    parts.push("ByVal value As Variant".to_string());
    parts.join(", ")
}

fn build_event_param_list(callback_arity: u8) -> String {
    (0..callback_arity)
        .map(|index| format!("ByVal arg{index} As Variant"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn build_reference_order_map(manifest: &ProjectManifest) -> BTreeMap<String, usize> {
    let mut out = BTreeMap::new();
    for (index, reference) in manifest.references.iter().enumerate() {
        out.insert(
            normalize_identifier(&reference.referenced_project_name),
            index,
        );
    }
    out
}

fn ordered_reference_projects(manifest: &ProjectManifest) -> Vec<&ReferencedProjectManifest> {
    let mut refs = manifest.reference_projects.iter().collect::<Vec<_>>();
    let order_map = build_reference_order_map(manifest);
    refs.sort_by_key(|referenced| {
        let key = normalize_identifier(&referenced.project_name);
        order_map.get(&key).copied().unwrap_or(usize::MAX)
    });
    refs
}

fn lowered_proc_symbol(
    project_name: &str,
    module_name: &str,
    procedure_name: &str,
    kind: ProcedureDeclKind,
) -> String {
    let base = lowered_proc_signature_symbol(project_name, module_name, procedure_name);
    match kind {
        ProcedureDeclKind::Sub | ProcedureDeclKind::Function => base,
        ProcedureDeclKind::PropertyGet => format!("property_get_{base}"),
        ProcedureDeclKind::PropertyLet => format!("property_let_{base}"),
        ProcedureDeclKind::PropertySet => format!("property_set_{base}"),
    }
}

fn lowered_proc_signature_symbol(
    project_name: &str,
    module_name: &str,
    procedure_name: &str,
) -> String {
    format!("pmr_{project_name}_{module_name}_{procedure_name}")
}

fn lowered_proc_signature_name(decl: &ProcedureDecl) -> &str {
    match decl.kind {
        ProcedureDeclKind::Sub | ProcedureDeclKind::Function => decl.lowered_name.as_str(),
        ProcedureDeclKind::PropertyGet => decl
            .lowered_name
            .strip_prefix("property_get_")
            .unwrap_or(decl.lowered_name.as_str()),
        ProcedureDeclKind::PropertyLet => decl
            .lowered_name
            .strip_prefix("property_let_")
            .unwrap_or(decl.lowered_name.as_str()),
        ProcedureDeclKind::PropertySet => decl
            .lowered_name
            .strip_prefix("property_set_")
            .unwrap_or(decl.lowered_name.as_str()),
    }
}

fn lowered_function_result_name(decl: &ProcedureDecl) -> &str {
    match decl.kind {
        ProcedureDeclKind::PropertyGet => lowered_proc_signature_name(decl),
        _ => decl.lowered_name.as_str(),
    }
}

fn find_decl_by_signature<'a>(
    procedures: &'a [ProcedureDecl],
    project_name: &str,
    module_name: &str,
    procedure_name: &str,
    kind: ProcedureDeclKind,
) -> Option<&'a ProcedureDecl> {
    procedures.iter().find(|decl| {
        decl.project_name == project_name
            && decl.module_name == module_name
            && decl.procedure_name == procedure_name
            && decl.kind == kind
    })
}

fn find_decl_by_name<'a>(
    procedures: &'a [ProcedureDecl],
    project_name: &str,
    module_name: &str,
    procedure_name: &str,
) -> Option<&'a ProcedureDecl> {
    procedures.iter().find(|decl| {
        decl.project_name == project_name
            && decl.module_name == module_name
            && decl.procedure_name == procedure_name
    })
}

fn is_visible_from_active_project(
    decl: &ProcedureDecl,
    active_project: &str,
    current_project: &str,
    current_module: &str,
) -> bool {
    if decl.project_name == current_project && decl.module_name == current_module {
        return true;
    }
    if decl.project_name == active_project {
        return decl.is_public;
    }
    decl.is_public && !decl.option_private_module
}

fn unique_lowered_name_for_proc(
    procedures: &[ProcedureDecl],
    project_name: &str,
    procedure_name: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
) -> Result<Option<String>, ProjectCompileError> {
    let candidates = procedures
        .iter()
        .filter(|decl| {
            decl.project_name == project_name
                && decl.procedure_name == procedure_name
                && is_visible_from_active_project(
                    decl,
                    active_project,
                    current_project,
                    current_module,
                )
        })
        .collect::<Vec<_>>();
    if candidates.is_empty() {
        return Ok(None);
    }
    if candidates.len() > 1 {
        return Err(ProjectCompileError::NameQualificationRequired {
            name: procedure_name.to_string(),
        });
    }
    Ok(Some(candidates[0].lowered_name.clone()))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct InvocationBinding {
    start: usize,
    end: usize,
    raw_name: String,
    replacement: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LineBindPlan {
    drop_line: bool,
    lowered_line: String,
    bound_call_targets: Vec<(String, String)>,
}

type EventDispatchKey = (String, String, String);
type EventDispatchPlan = BTreeMap<EventDispatchKey, Vec<EventDispatchRoute>>;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct EventDispatchRoute {
    handler_symbol: String,
    sink_project_name: String,
    sink_module_name: String,
    withevents_var: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct EarlyBoundBinding {
    qualified_type: String,
    typelib_metadata: Option<TypeLibMetadataBlob>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct InternalClassBinding {
    project_name: String,
    module_name: String,
    generated_instance_id: Option<i32>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ExternalDimDecl {
    leading_ws: String,
    var_name: String,
    qualified_type: String,
    as_new: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct InternalClassDimDecl {
    leading_ws: String,
    var_name: String,
    type_name: String,
    as_new: bool,
}

#[allow(clippy::too_many_arguments)]
fn lower_module_source_module_aware(
    manifest: &ProjectManifest,
    active_project: &str,
    module: &ModuleUnit,
    current_project: &str,
    procedures: &[ProcedureDecl],
    reference_order: &BTreeMap<String, usize>,
    event_dispatch_plan: &EventDispatchPlan,
    next_internal_instance_id: &mut i32,
    dynamic_instance_bindings: &mut Vec<ProjectDynamicInstanceBindingDraft>,
) -> Result<(String, BTreeMap<String, BTreeSet<String>>), ProjectCompileError> {
    let current_module = normalize_identifier(&module.module_name);
    let imported_collection_newenum_fields =
        collect_internal_class_imported_collection_newenum_fields(module);
    let mut out = Vec::new();
    let mut active_function_result: Option<(String, String)> = None;
    let mut active_procedure_name: Option<String> = None;
    let mut early_bound = BTreeMap::<String, EarlyBoundBinding>::new();
    let mut internal_class_bindings = BTreeMap::<String, InternalClassBinding>::new();
    let mut forced_object_locals_by_proc = ForcedObjectLocalsByProc::new();
    let mut withevents_bindings = BTreeSet::<String>::new();
    let (module_shadowed_identifiers, shadowed_identifiers_by_proc) =
        collect_module_shadowed_identifiers(module);
    let module_state_bindings =
        collect_module_state_bindings(module, current_project, &current_module);
    let source_lines = module_source_lines_with_class_terminate_cleanup(module);
    for line in &source_lines {
        record_internal_class_object_local(
            &mut forced_object_locals_by_proc,
            &active_procedure_name,
            line,
            manifest,
            current_project,
            reference_order,
        )?;
        let expanded = expand_bound_source_line(
            line,
            manifest,
            current_project,
            reference_order,
            procedures,
            &mut early_bound,
            &mut internal_class_bindings,
            &mut withevents_bindings,
            next_internal_instance_id,
            dynamic_instance_bindings,
        )?;
        for expanded_line in expanded {
            let shadowed_identifiers = visible_shadowed_identifiers(
                &module_shadowed_identifiers,
                &shadowed_identifiers_by_proc,
                procedures,
                current_project,
                &current_module,
                active_procedure_name.as_deref(),
            );
            let expanded_line = rewrite_internal_class_set_assignment(
                manifest,
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
                &withevents_bindings,
            )?;
            let expanded_line = rewrite_internal_class_property_assignment(
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
            )?;
            let expanded_line = rewrite_internal_class_default_member_assignment(
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
            )?;
            let expanded_line = rewrite_internal_class_collection_member_calls(
                &expanded_line,
                &module_state_bindings,
                &imported_collection_newenum_fields,
            )?;
            let expanded_line = rewrite_internal_class_collection_newenum_read_assignment(
                &expanded_line,
                &module_state_bindings,
                &imported_collection_newenum_fields,
            );
            let expanded_line = rewrite_internal_class_imported_collection_activation(
                &expanded_line,
                &module_state_bindings,
                &imported_collection_newenum_fields,
            );
            let state_assigned =
                rewrite_internal_class_state_assignment(&expanded_line, &module_state_bindings);
            let expanded_line = if state_assigned != expanded_line {
                state_assigned
            } else {
                rewrite_internal_class_state_reads(&state_assigned, &module_state_bindings)
            };
            let expanded_line = rewrite_internal_class_default_member_read_assignment(
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
            )?;
            let expanded_line = rewrite_internal_class_property_reads(
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
            )?;
            let expanded_line = rewrite_internal_class_member_dispatch(
                &expanded_line,
                active_project,
                current_project,
                &current_module,
                procedures,
                &internal_class_bindings,
                &shadowed_identifiers,
            )?;
            let next_active_procedure_name = lowered_procedure_binding_for_line(
                &expanded_line,
                procedures,
                current_project,
                &current_module,
            );
            let (plan, next_function_result) = build_line_bind_plan(
                manifest,
                active_project,
                module,
                current_project,
                &current_module,
                procedures,
                reference_order,
                event_dispatch_plan,
                &expanded_line,
                active_function_result.as_ref(),
            )?;
            active_function_result = next_function_result;
            let _ = &plan.bound_call_targets;
            if plan.drop_line {
                continue;
            }
            out.push(plan.lowered_line.clone());
            if let Some(proc_name) = next_active_procedure_name {
                active_procedure_name = Some(proc_name);
            } else {
                clear_active_procedure_name_if_end(&mut active_procedure_name, &plan.lowered_line);
            }
        }
    }
    out.extend(emit_event_guard_wrappers_for_module(
        current_project,
        &current_module,
        event_dispatch_plan,
        procedures,
        &withevents_bindings,
    ));
    Ok((out.join("\n"), forced_object_locals_by_proc))
}

fn module_source_lines_with_class_terminate_cleanup(module: &ModuleUnit) -> Vec<String> {
    if module.module_kind != ModuleKind::Class {
        return module.source.lines().map(|line| line.to_string()).collect();
    }

    let mut out = Vec::new();
    let mut in_class_terminate = false;
    for line in module.source.lines() {
        let normalized = normalize_visibility_prefixed_procedure_signature(line);
        if let Some((proc_name, _, _)) = parse_procedure_signature_line(&normalized) {
            in_class_terminate = proc_name.eq_ignore_ascii_case("class_terminate");
        }

        let lower = line.trim().to_ascii_lowercase();
        if in_class_terminate && lower == "end sub" {
            let leading_ws_len = line.len().saturating_sub(line.trim_start().len());
            let leading_ws = &line[..leading_ws_len];
            let cleanup_line = format!(
                "{leading_ws}__oxvba_this_instance = __oxvba_withevents_clear_owner(__oxvba_this_instance)"
            );
            let already_injected = out
                .last()
                .map(|prior: &String| prior.trim().eq_ignore_ascii_case(cleanup_line.trim()))
                .unwrap_or(false);
            if !already_injected {
                out.push(cleanup_line);
            }
            in_class_terminate = false;
        }
        out.push(line.to_string());
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn expand_bound_source_line(
    line: &str,
    manifest: &ProjectManifest,
    current_project: &str,
    reference_order: &BTreeMap<String, usize>,
    procedures: &[ProcedureDecl],
    early_bound: &mut BTreeMap<String, EarlyBoundBinding>,
    internal_class_bindings: &mut BTreeMap<String, InternalClassBinding>,
    withevents_bindings: &mut BTreeSet<String>,
    next_internal_instance_id: &mut i32,
    dynamic_instance_bindings: &mut Vec<ProjectDynamicInstanceBindingDraft>,
) -> Result<Vec<String>, ProjectCompileError> {
    if let Some(dim_decl) = parse_external_dim_declaration(line) {
        let (qualifier, _) = parse_qualified_type_reference(&dim_decl.qualified_type)
            .expect("external dim declaration must carry qualified type");
        let qualifier = qualifier.to_string();
        let Some((source_project, source_module, blob)) =
            referenced_typelib_blob_for_type_reference(manifest, &dim_decl.qualified_type)?
        else {
            return Err(ProjectCompileError::TypeLibraryQualifierUnresolved {
                type_name: dim_decl.qualified_type,
                qualifier,
            });
        };
        let activation_prog_id =
            activation_prog_id_from_typelib_metadata(&blob).map(str::to_string);
        if dim_decl.as_new && activation_prog_id.is_none() {
            return Err(ProjectCompileError::TypeLibraryCreateObjectUnsupported {
                type_name: dim_decl.qualified_type,
            });
        }
        early_bound.insert(
            normalize_identifier(&dim_decl.var_name),
            EarlyBoundBinding {
                qualified_type: format!("{source_project}.{source_module}"),
                typelib_metadata: Some(blob),
            },
        );
        let mut out = Vec::new();
        out.push(format!(
            "{}Dim {} As Object",
            dim_decl.leading_ws, dim_decl.var_name
        ));
        if dim_decl.as_new {
            let prog_id = activation_prog_id.expect("checked above for As New");
            out.push(format!(
                "{}Set {} = CreateObject(\"{}\")",
                dim_decl.leading_ws, dim_decl.var_name, prog_id
            ));
        }
        return Ok(out);
    }

    if let Some(dim_decl) = parse_internal_class_dim_declaration(line)
        && let Some((target_project, target_module)) = resolve_interface_module(
            manifest,
            current_project,
            &dim_decl.type_name,
            reference_order,
        )?
    {
        internal_class_bindings.insert(
            normalize_identifier(&dim_decl.var_name),
            InternalClassBinding {
                project_name: target_project.clone(),
                module_name: target_module.clone(),
                generated_instance_id: dim_decl.as_new.then_some(*next_internal_instance_id),
            },
        );
        let mut out = vec![format!("{}Dim {}", dim_decl.leading_ws, dim_decl.var_name)];
        if dim_decl.as_new {
            let object_handle = ObjectHandle::new(*next_internal_instance_id);
            dynamic_instance_bindings.push(ProjectDynamicInstanceBindingDraft {
                object_handle,
                project_name: target_project.clone(),
                module_name: target_module.clone(),
            });
            out.push(format!(
                "{}{} = {}",
                dim_decl.leading_ws, dim_decl.var_name, *next_internal_instance_id
            ));
            if let Some(class_initialize) = find_decl_by_signature(
                procedures,
                &target_project,
                &target_module,
                "class_initialize",
                ProcedureDeclKind::Sub,
            ) {
                out.push(format!(
                    "{}Call {}({})",
                    dim_decl.leading_ws,
                    class_initialize.lowered_name,
                    object_handle.raw()
                ));
            }
            *next_internal_instance_id = next_internal_instance_id.saturating_add(1);
        }
        return Ok(out);
    }
    if let Some(dim_decl) = parse_internal_class_dim_declaration(line)
        && let Some((source_project, source_module, blob)) =
            referenced_typelib_blob_for_type_reference(manifest, &dim_decl.type_name)?
    {
        let activation_prog_id = blob.activation_prog_id.clone();
        if dim_decl.as_new && activation_prog_id.is_none() {
            return Err(ProjectCompileError::TypeLibraryCreateObjectUnsupported {
                type_name: dim_decl.type_name,
            });
        }
        early_bound.insert(
            normalize_identifier(&dim_decl.var_name),
            EarlyBoundBinding {
                qualified_type: format!("{source_project}.{source_module}"),
                typelib_metadata: Some(blob),
            },
        );
        let mut out = vec![format!(
            "{}Dim {} As Object",
            dim_decl.leading_ws, dim_decl.var_name
        )];
        if dim_decl.as_new {
            let prog_id = activation_prog_id.expect("checked above for As New");
            out.push(format!(
                "{}Set {} = CreateObject(\"{}\")",
                dim_decl.leading_ws, dim_decl.var_name, prog_id
            ));
        }
        return Ok(out);
    }

    if let Some((withevents_var, source_type)) = parse_withevents_declaration_binding(line) {
        if let Some((target_project, target_module)) =
            resolve_event_source_module(manifest, current_project, &source_type, reference_order)?
        {
            let leading_ws_len = line.len().saturating_sub(line.trim_start().len());
            let leading_ws = &line[..leading_ws_len];
            internal_class_bindings.insert(
                normalize_identifier(&withevents_var),
                InternalClassBinding {
                    project_name: target_project,
                    module_name: target_module,
                    generated_instance_id: None,
                },
            );
            withevents_bindings.insert(normalize_identifier(&withevents_var));
            return Ok(vec![format!("{leading_ws}Public {withevents_var}")]);
        }
        if let Some((source_project, source_module, blob)) =
            referenced_typelib_blob_for_type_reference(manifest, &source_type)?
        {
            // Phase 3A: Imported typelib WithEvents types are treated as plain
            // Public variable declarations for member dispatch, but they still
            // participate in runtime WithEvents binding/guard emission.
            let leading_ws_len = line.len().saturating_sub(line.trim_start().len());
            let leading_ws = &line[..leading_ws_len];
            early_bound.insert(
                normalize_identifier(&withevents_var),
                EarlyBoundBinding {
                    qualified_type: format!("{source_project}.{source_module}"),
                    typelib_metadata: Some(blob),
                },
            );
            withevents_bindings.insert(normalize_identifier(&withevents_var));
            return Ok(vec![format!("{leading_ws}Public {withevents_var}")]);
        }
    }

    let rewritten = rewrite_early_bound_property_assignment(line, early_bound)?;
    let rewritten = rewrite_early_bound_object_assignment(manifest, &rewritten, early_bound)?;
    let rewritten = rewrite_early_bound_property_read_assignment(&rewritten, early_bound)?;
    let rewritten = rewrite_early_bound_member_dispatch(&rewritten, early_bound)?;
    let rewritten = rewrite_early_bound_call_statement_without_parens(&rewritten, early_bound)?;
    let rewritten =
        rewrite_early_bound_statement_invoke_without_parentheses(&rewritten, early_bound)?;
    Ok(vec![rewritten])
}

fn parse_external_dim_declaration(line: &str) -> Option<ExternalDimDecl> {
    let leading_ws_len = line.len().saturating_sub(line.trim_start().len());
    let leading_ws = line[..leading_ws_len].to_string();
    let trimmed = line.trim();
    if !trimmed.to_ascii_lowercase().starts_with("dim ") {
        return None;
    }
    let payload = trimmed[4..].trim();
    if payload.contains(',') {
        return None;
    }
    let (lhs, rhs) = split_keyword_ascii_ci(payload, " as ")?;
    let var_name = lhs.trim();
    if var_name.is_empty() || !is_valid_vba_identifier(var_name) {
        return None;
    }
    let mut rhs_trimmed = rhs.trim();
    let as_new = if rhs_trimmed.len() >= 4 && rhs_trimmed[..4].eq_ignore_ascii_case("new ") {
        rhs_trimmed = rhs_trimmed[4..].trim();
        true
    } else {
        false
    };
    let (_, normalized_type) = parse_qualified_type_reference(rhs_trimmed)?;
    Some(ExternalDimDecl {
        leading_ws,
        var_name: var_name.to_string(),
        qualified_type: normalized_type,
        as_new,
    })
}

fn parse_internal_class_dim_declaration(line: &str) -> Option<InternalClassDimDecl> {
    let leading_ws_len = line.len().saturating_sub(line.trim_start().len());
    let leading_ws = line[..leading_ws_len].to_string();
    let trimmed = line.trim();
    if !trimmed.to_ascii_lowercase().starts_with("dim ") {
        return None;
    }
    let payload = trimmed[4..].trim();
    if payload.contains(',') {
        return None;
    }
    let (lhs, rhs) = split_keyword_ascii_ci(payload, " as ")?;
    let var_name = lhs.trim();
    if var_name.is_empty() || !is_valid_vba_identifier(var_name) {
        return None;
    }
    let mut rhs_trimmed = rhs.trim();
    let as_new = if rhs_trimmed.len() >= 4 && rhs_trimmed[..4].eq_ignore_ascii_case("new ") {
        rhs_trimmed = rhs_trimmed[4..].trim();
        true
    } else {
        false
    };
    let type_token = rhs_trimmed
        .split(|ch: char| ch.is_ascii_whitespace() || ch == '(')
        .next()
        .unwrap_or_default()
        .trim();
    if type_token.is_empty() {
        return None;
    }
    let type_name = type_token
        .split('.')
        .next_back()
        .map(normalize_identifier)?;
    if type_name.is_empty() {
        return None;
    }
    Some(InternalClassDimDecl {
        leading_ws,
        var_name: var_name.to_string(),
        type_name,
        as_new,
    })
}

fn parse_qualified_type_reference(type_text: &str) -> Option<(&str, String)> {
    let raw = type_text.trim();
    if raw.is_empty() {
        return None;
    }
    let mut parts = raw.split('.');
    let qualifier = parts.next()?.trim();
    if !is_valid_vba_identifier(qualifier) {
        return None;
    }
    let mut normalized = vec![qualifier.to_string()];
    let mut saw_tail = false;
    for part in parts {
        let token = part.trim();
        if !is_valid_vba_identifier(token) {
            return None;
        }
        normalized.push(token.to_string());
        saw_tail = true;
    }
    if !saw_tail {
        return None;
    }
    Some((qualifier, normalized.join(".")))
}

fn is_referenced_typelib_type_reference(manifest: &ProjectManifest, type_text: &str) -> bool {
    referenced_typelib_blob_for_type_reference(manifest, type_text)
        .ok()
        .flatten()
        .is_some()
}

fn referenced_typelib_blob_for_project_module(
    manifest: &ProjectManifest,
    project_name: &str,
    module_name: &str,
) -> Result<Option<TypeLibMetadataBlob>, ProjectCompileError> {
    let normalized_project = normalize_identifier(project_name);
    let normalized_module = normalize_identifier(module_name);
    for project in ordered_reference_projects(manifest) {
        if normalize_identifier(&project.project_name) != normalized_project {
            continue;
        }
        let Some(module) = project.modules.iter().find(|module| {
            module.module_kind == ModuleKind::Class
                && normalize_identifier(&module.module_name) == normalized_module
        }) else {
            continue;
        };
        if let Some(err) = referenced_project_typelib_binding_diagnostic(project)? {
            return Err(err);
        }
        if let Some(provenance) = projected_typelib_reference_provenance(project) {
            let mut identity = provenance.identity;
            if identity.requested_coclass.is_none() {
                identity.requested_coclass = Some(module.module_name.clone());
            }
            return Ok(Some(build_typelib_metadata(&identity)));
        }
        if let Some(identity) =
            resolve_typelib_identity_for_project_module(&project.project_name, &module.module_name)
        {
            return Ok(Some(build_typelib_metadata(&identity)));
        }
    }
    Ok(None)
}

fn referenced_typelib_blob_for_type_reference(
    manifest: &ProjectManifest,
    type_text: &str,
) -> Result<Option<(String, String, TypeLibMetadataBlob)>, ProjectCompileError> {
    let raw = type_text.trim();
    if raw.is_empty() {
        return Ok(None);
    }

    if let Some((qualifier, normalized_type)) = parse_qualified_type_reference(raw) {
        let normalized_project = normalize_identifier(qualifier);
        let normalized_module = normalize_identifier(
            normalized_type
                .rsplit('.')
                .next()
                .unwrap_or_default()
                .trim(),
        );
        if let Some(blob) =
            referenced_typelib_blob_for_project_module(manifest, qualifier, &normalized_module)?
        {
            return Ok(Some((normalized_project, normalized_module, blob)));
        }
        let referenced = manifest.references.iter().any(|reference| {
            reference.reference_kind == ReferenceKind::TypeLibrary
                && normalize_identifier(&reference.referenced_project_name) == normalized_project
        }) || manifest
            .reference_projects
            .iter()
            .any(|project| normalize_identifier(&project.project_name) == normalized_project);
        if referenced
            && let Some(identity) =
                resolve_typelib_identity_for_project_module(&normalized_project, &normalized_module)
        {
            return Ok(Some((
                normalized_project,
                normalized_module,
                build_typelib_metadata(&identity),
            )));
        }
        return Ok(None);
    }

    if !is_valid_vba_identifier(raw) {
        return Ok(None);
    }

    let normalized_module = normalize_identifier(raw);
    for project in ordered_reference_projects(manifest) {
        if project.modules.iter().any(|module| {
            module.module_kind == ModuleKind::Class
                && normalize_identifier(&module.module_name) == normalized_module
        }) {
            if let Some(blob) =
                referenced_typelib_blob_for_project_module(manifest, &project.project_name, raw)?
            {
                return Ok(Some((
                    normalize_identifier(&project.project_name),
                    normalize_identifier(raw),
                    blob,
                )));
            }
        }
    }

    for reference in &manifest.references {
        if reference.reference_kind != ReferenceKind::TypeLibrary {
            continue;
        }
        let Some(identity) =
            resolve_typelib_identity_for_project_module(&reference.referenced_project_name, raw)
        else {
            continue;
        };
        return Ok(Some((
            normalize_identifier(&reference.referenced_project_name),
            normalize_identifier(raw),
            build_typelib_metadata(&identity),
        )));
    }

    Ok(None)
}

fn resolve_typelib_identity_for_project_module(
    project_name: &str,
    module_name: &str,
) -> Option<oxvba_com::TypeLibResolvedIdentity> {
    resolve_known_typelib_identity(&TypeLibResolveRequest {
        reference_name: project_name.to_string(),
        requested_coclass: Some(module_name.to_string()),
        importlib_hint: None,
        libid_hint: None,
        major_version_hint: None,
        minor_version_hint: None,
        lcid_hint: None,
    })
    .or_else(|| resolve_typelib_identity_for_prog_id_name(&format!("{project_name}.{module_name}")))
}

fn resolve_typelib_identity_for_reference(
    reference_name: &str,
) -> Option<oxvba_com::TypeLibResolvedIdentity> {
    resolve_known_typelib_identity(&TypeLibResolveRequest {
        reference_name: reference_name.to_string(),
        requested_coclass: None,
        importlib_hint: None,
        libid_hint: None,
        major_version_hint: None,
        minor_version_hint: None,
        lcid_hint: None,
    })
}

fn referenced_typelib_event_source(
    manifest: &ProjectManifest,
    type_text: &str,
) -> Result<Option<(String, String, BTreeSet<String>)>, ProjectCompileError> {
    let Some((project_name, module_name, blob)) =
        referenced_typelib_blob_for_type_reference(manifest, type_text)?
    else {
        return Ok(None);
    };
    let events = blob
        .events
        .iter()
        .map(|event| normalize_identifier(&event.name))
        .collect::<BTreeSet<_>>();
    if events.is_empty() {
        return Ok(None);
    }
    Ok(Some((project_name, module_name, events)))
}

fn rewrite_typelib_new_expression(
    manifest: &ProjectManifest,
    expr: &str,
) -> Result<String, ProjectCompileError> {
    let trimmed = expr.trim();
    if trimmed.len() < 4 || !trimmed[..4].eq_ignore_ascii_case("new ") {
        return Ok(expr.to_string());
    }
    let type_text = trimmed[4..].trim();
    let Some((_, _, blob)) = referenced_typelib_blob_for_type_reference(manifest, type_text)?
    else {
        return Ok(expr.to_string());
    };
    let Some(prog_id) = activation_prog_id_from_typelib_metadata(&blob) else {
        return Err(ProjectCompileError::TypeLibraryCreateObjectUnsupported {
            type_name: type_text.to_string(),
        });
    };
    Ok(format!("CreateObject(\"{prog_id}\")"))
}

fn rewrite_early_bound_member_dispatch(
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    let mut replacements: Vec<(usize, usize, String)> = Vec::new();
    let mut cursor = 0usize;
    while let Some(open_rel) = line[cursor..].find('(') {
        let open = cursor + open_rel;
        let Some((name_start, name_end)) = invocation_name_span(line, open) else {
            cursor = open + 1;
            continue;
        };
        let Some(close) = find_matching_paren(line, open) else {
            cursor = open + 1;
            continue;
        };
        let raw_name = line[name_start..name_end].trim();
        let (var_name, target_name, member_token, member_spec) =
            if let Some(dot_idx) = raw_name.find('.') {
                let var_name = raw_name[..dot_idx].trim();
                let member_name = raw_name[dot_idx + 1..].trim();
                if var_name.is_empty() || member_name.is_empty() {
                    cursor = close + 1;
                    continue;
                }
                let key = normalize_identifier(var_name);
                let Some(binding) = early_bound.get(&key) else {
                    cursor = close + 1;
                    continue;
                };
                let target_name = format!("{}.{}", binding.qualified_type, member_name);
                let (member_token, member_spec) =
                    match resolve_early_bound_binding_member_token_and_spec(binding, member_name) {
                        KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                            (member_token, member_spec)
                        }
                        KnownTypeLibMemberResolution::Unsupported => {
                            return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                                member_name: member_name.to_string(),
                            });
                        }
                        KnownTypeLibMemberResolution::Missing => {
                            return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                                target: target_name,
                            });
                        }
                        KnownTypeLibMemberResolution::Ambiguous => {
                            return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                                target: target_name,
                            });
                        }
                    };
                (var_name.to_string(), target_name, member_token, member_spec)
            } else {
                let var_name = raw_name.trim();
                if var_name.is_empty() {
                    cursor = close + 1;
                    continue;
                }
                let key = normalize_identifier(var_name);
                let Some(binding) = early_bound.get(&key) else {
                    cursor = close + 1;
                    continue;
                };
                let default_target = format!("{}.<default>", binding.qualified_type);
                let (member_token, member_spec) =
                    match resolve_early_bound_binding_default_member_token_and_spec(binding) {
                        KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                            (member_token, member_spec)
                        }
                        KnownTypeLibMemberResolution::Unsupported => {
                            return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                                member_name: default_target,
                            });
                        }
                        KnownTypeLibMemberResolution::Missing => {
                            return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                                target: default_target,
                            });
                        }
                        KnownTypeLibMemberResolution::Ambiguous => {
                            return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                                target: default_target,
                            });
                        }
                    };
                (
                    var_name.to_string(),
                    format!("{}.{}", binding.qualified_type, member_spec.name),
                    member_token,
                    member_spec,
                )
            };
        if !matches!(
            member_spec.invoke_kind,
            TypeLibMemberInvokeKind::PropertyGet | TypeLibMemberInvokeKind::Method
        ) {
            return Err(ProjectCompileError::TypeLibraryMemberShapeUnsupported {
                target: target_name.clone(),
                shape: render_typelib_invoke_kind(member_spec.invoke_kind).to_string(),
            });
        }
        let args_raw = line[open + 1..close].trim();
        let args = split_top_level_args(args_raw)?;
        let actual_arity = args.iter().filter(|arg| !arg.trim().is_empty()).count();
        let expected_arity = member_spec.parameter_names.len();
        if actual_arity != expected_arity {
            return Err(ProjectCompileError::TypeLibraryInvokeArityUnsupported {
                target: target_name,
                expected: expected_arity,
                actual: actual_arity,
            });
        }
        let replacement = if args.is_empty() || args.iter().all(|arg| arg.trim().is_empty()) {
            format!("DispatchInvoke({var_name}, {member_token})")
        } else {
            let rendered_args = args
                .iter()
                .map(|arg| arg.trim())
                .filter(|arg| !arg.is_empty())
                .collect::<Vec<_>>()
                .join(", ");
            format!("DispatchInvoke({var_name}, {member_token}, {rendered_args})")
        };
        replacements.push((name_start, close + 1, replacement));
        cursor = close + 1;
    }
    if replacements.is_empty() {
        return Ok(line.to_string());
    }
    let mut out = String::with_capacity(line.len() + 32);
    let mut previous = 0usize;
    for (start, end, replacement) in replacements {
        if start < previous || end > line.len() || start >= end {
            continue;
        }
        out.push_str(&line[previous..start]);
        out.push_str(&replacement);
        previous = end;
    }
    out.push_str(&line[previous..]);
    Ok(out)
}

fn resolve_early_bound_invoke_target(
    raw_name: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<Option<(String, String, i32, ComMemberSpec)>, ProjectCompileError> {
    if let Some(dot_idx) = raw_name.find('.') {
        let var_name = raw_name[..dot_idx].trim();
        let member_name = raw_name[dot_idx + 1..].trim();
        if var_name.is_empty() || member_name.is_empty() {
            return Ok(None);
        }
        let key = normalize_identifier(var_name);
        let Some(binding) = early_bound.get(&key) else {
            return Ok(None);
        };
        let target_name = format!("{}.{}", binding.qualified_type, member_name);
        let (member_token, member_spec) =
            match resolve_early_bound_binding_member_token_and_spec(binding, member_name) {
                KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                    (member_token, member_spec)
                }
                KnownTypeLibMemberResolution::Unsupported => {
                    return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                        member_name: member_name.to_string(),
                    });
                }
                KnownTypeLibMemberResolution::Missing => {
                    return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                        target: target_name,
                    });
                }
                KnownTypeLibMemberResolution::Ambiguous => {
                    return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                        target: target_name,
                    });
                }
            };
        Ok(Some((
            var_name.to_string(),
            format!("{}.{}", binding.qualified_type, member_spec.name),
            member_token,
            member_spec,
        )))
    } else {
        let var_name = raw_name.trim();
        if var_name.is_empty() {
            return Ok(None);
        }
        let key = normalize_identifier(var_name);
        let Some(binding) = early_bound.get(&key) else {
            return Ok(None);
        };
        let default_target = format!("{}.<default>", binding.qualified_type);
        let (member_token, member_spec) =
            match resolve_early_bound_binding_default_member_token_and_spec(binding) {
                KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                    (member_token, member_spec)
                }
                KnownTypeLibMemberResolution::Unsupported => {
                    return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                        member_name: default_target,
                    });
                }
                KnownTypeLibMemberResolution::Missing => {
                    return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                        target: default_target,
                    });
                }
                KnownTypeLibMemberResolution::Ambiguous => {
                    return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                        target: default_target,
                    });
                }
            };
        Ok(Some((
            var_name.to_string(),
            format!("{}.{}", binding.qualified_type, member_spec.name),
            member_token,
            member_spec,
        )))
    }
}

fn validate_early_bound_invoke_shape(
    target_name: &str,
    member_spec: ComMemberSpec,
    actual_arity: usize,
) -> Result<(), ProjectCompileError> {
    if !matches!(
        member_spec.invoke_kind,
        TypeLibMemberInvokeKind::PropertyGet | TypeLibMemberInvokeKind::Method
    ) {
        return Err(ProjectCompileError::TypeLibraryMemberShapeUnsupported {
            target: target_name.to_string(),
            shape: render_typelib_invoke_kind(member_spec.invoke_kind).to_string(),
        });
    }
    let expected_arity = member_spec.parameter_names.len();
    if actual_arity != expected_arity {
        return Err(ProjectCompileError::TypeLibraryInvokeArityUnsupported {
            target: target_name.to_string(),
            expected: expected_arity,
            actual: actual_arity,
        });
    }
    Ok(())
}

fn render_dispatch_invoke(var_name: &str, member_token: i32, args: &[String]) -> String {
    if args.is_empty() {
        format!("DispatchInvoke({var_name}, {member_token})")
    } else {
        let rendered_args = args
            .iter()
            .map(|arg| arg.trim())
            .filter(|arg| !arg.is_empty())
            .collect::<Vec<_>>()
            .join(", ");
        format!("DispatchInvoke({var_name}, {member_token}, {rendered_args})")
    }
}

fn rewrite_early_bound_call_statement_without_parens(
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    if early_bound.is_empty() {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("call ") {
        return Ok(line.to_string());
    }
    let payload = trimmed[5..].trim_start();
    if payload.is_empty()
        || payload.contains('(')
        || find_top_level_assignment_eq(payload).is_some()
    {
        return Ok(line.to_string());
    }
    let callee_end = payload.find(char::is_whitespace).unwrap_or(payload.len());
    let callee = payload[..callee_end].trim();
    if callee.is_empty() {
        return Ok(line.to_string());
    }
    let args_tail = payload[callee_end..].trim();
    let Some((var_name, target_name, member_token, member_spec)) =
        resolve_early_bound_invoke_target(callee, early_bound)?
    else {
        return Ok(line.to_string());
    };
    let args = if args_tail.is_empty() {
        Vec::new()
    } else {
        split_top_level_args(args_tail)?
            .into_iter()
            .map(|arg| arg.trim().to_string())
            .filter(|arg| !arg.is_empty())
            .collect::<Vec<_>>()
    };
    validate_early_bound_invoke_shape(&target_name, member_spec, args.len())?;
    Ok(format!(
        "{}Call {}",
        &line[..leading],
        render_dispatch_invoke(&var_name, member_token, &args)
    ))
}

fn rewrite_early_bound_statement_invoke_without_parentheses(
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    if early_bound.is_empty() {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if trimmed.is_empty()
        || lower.starts_with("call ")
        || trimmed.contains('(')
        || find_top_level_assignment_eq(trimmed).is_some()
    {
        return Ok(line.to_string());
    }
    let callee_end = trimmed.find(char::is_whitespace).unwrap_or(trimmed.len());
    let callee = trimmed[..callee_end].trim();
    let args_tail = trimmed[callee_end..].trim();
    if callee.is_empty() {
        return Ok(line.to_string());
    }
    let Some((var_name, target_name, member_token, member_spec)) =
        resolve_early_bound_invoke_target(callee, early_bound)?
    else {
        return Ok(line.to_string());
    };
    let args = if args_tail.is_empty() {
        Vec::new()
    } else {
        split_top_level_args(args_tail)?
            .into_iter()
            .map(|arg| arg.trim().to_string())
            .filter(|arg| !arg.is_empty())
            .collect::<Vec<_>>()
    };
    validate_early_bound_invoke_shape(&target_name, member_spec, args.len())?;
    Ok(format!(
        "{}{}",
        &line[..leading],
        render_dispatch_invoke(&var_name, member_token, &args)
    ))
}

fn rewrite_early_bound_property_assignment(
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    if early_bound.is_empty() || class_state_line_is_non_executable(line) {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    let explicit_set = lowered.starts_with("set ");
    let explicit_let = lowered.starts_with("let ");
    let payload = if explicit_set || explicit_let {
        trimmed[4..].trim_start()
    } else {
        trimmed
    };
    let Some(eq_idx) = find_top_level_assignment_eq(payload) else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() {
        return Ok(line.to_string());
    }
    let Some(dot_idx) = lhs.find('.') else {
        return Ok(line.to_string());
    };
    let var_name = lhs[..dot_idx].trim();
    let Some(binding) = early_bound.get(&normalize_identifier(var_name)) else {
        return Ok(line.to_string());
    };
    let member_expr = lhs[dot_idx + 1..].trim();
    let (member_name, mut args) = if let Some(open_idx) = member_expr.find('(') {
        let Some(close_idx) = find_matching_paren(member_expr, open_idx) else {
            return Ok(line.to_string());
        };
        if close_idx != member_expr.len().saturating_sub(1) {
            return Ok(line.to_string());
        }
        let member_name = member_expr[..open_idx].trim();
        if member_name.is_empty() {
            return Ok(line.to_string());
        }
        let args = split_top_level_args(member_expr[open_idx + 1..close_idx].trim())?
            .into_iter()
            .filter(|arg| !arg.trim().is_empty())
            .collect::<Vec<_>>();
        (member_name.to_string(), args)
    } else {
        if member_expr.is_empty() {
            return Ok(line.to_string());
        }
        (member_expr.to_string(), Vec::new())
    };
    let target_name = format!("{}.{}", binding.qualified_type, member_name);
    let (member_token, member_spec) =
        match resolve_early_bound_binding_member_token_and_spec(binding, &member_name) {
            KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                (member_token, member_spec)
            }
            KnownTypeLibMemberResolution::Unsupported => {
                return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                    member_name: member_name.to_string(),
                });
            }
            KnownTypeLibMemberResolution::Missing => {
                return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                    target: target_name,
                });
            }
            KnownTypeLibMemberResolution::Ambiguous => {
                return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                    target: target_name,
                });
            }
        };
    let supported_assignment_shape = if explicit_set {
        member_spec.invoke_kind == TypeLibMemberInvokeKind::PropertyPutRef
    } else {
        member_spec.invoke_kind == TypeLibMemberInvokeKind::PropertyPut
    };
    if !supported_assignment_shape {
        return Err(ProjectCompileError::TypeLibraryMemberShapeUnsupported {
            target: format!("{}.{}", binding.qualified_type, member_spec.name),
            shape: render_typelib_invoke_kind(member_spec.invoke_kind).to_string(),
        });
    }
    let has_named_args = args.iter().any(|arg| arg.contains(":="));
    if has_named_args {
        let value_name = member_spec
            .parameter_names
            .last()
            .cloned()
            .unwrap_or_else(|| "value".to_string());
        args.push(format!("{value_name} := {rhs}"));
    } else {
        args.push(rhs.to_string());
    }
    let actual_arity = args.iter().filter(|arg| !arg.trim().is_empty()).count();
    let expected_arity = member_spec.parameter_names.len();
    if actual_arity != expected_arity {
        return Err(ProjectCompileError::TypeLibraryInvokeArityUnsupported {
            target: format!("{}.{}", binding.qualified_type, member_spec.name),
            expected: expected_arity,
            actual: actual_arity,
        });
    }
    let rendered_args = args
        .iter()
        .map(|arg| arg.trim())
        .filter(|arg| !arg.is_empty())
        .collect::<Vec<_>>()
        .join(", ");
    Ok(format!(
        "{}Call DispatchInvoke({}, {}, {})",
        &line[..leading],
        var_name,
        member_token,
        rendered_args
    ))
}

fn rewrite_early_bound_property_read_assignment(
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    if early_bound.is_empty() || class_state_line_is_non_executable(line) {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    let explicit_set = lowered.starts_with("set ");
    let explicit_let = lowered.starts_with("let ");
    let payload = if explicit_set || explicit_let {
        trimmed[4..].trim_start()
    } else {
        trimmed
    };
    let Some(eq_idx) = payload.find('=') else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() || rhs.contains('(') || rhs.contains(char::is_whitespace) {
        return Ok(line.to_string());
    }
    let Some(dot_idx) = rhs.find('.') else {
        return Ok(line.to_string());
    };
    let var_name = rhs[..dot_idx].trim();
    let Some(binding) = early_bound.get(&normalize_identifier(var_name)) else {
        return Ok(line.to_string());
    };
    let member_name = rhs[dot_idx + 1..].trim();
    if member_name.is_empty() {
        return Ok(line.to_string());
    }
    let target_name = format!("{}.{}", binding.qualified_type, member_name);
    let (member_token, member_spec) =
        match resolve_early_bound_binding_member_token_and_spec(binding, member_name) {
            KnownTypeLibMemberResolution::Resolved(member_token, member_spec) => {
                (member_token, member_spec)
            }
            KnownTypeLibMemberResolution::Unsupported => {
                return Err(ProjectCompileError::TypeLibraryMemberUnsupported {
                    member_name: member_name.to_string(),
                });
            }
            KnownTypeLibMemberResolution::Missing => {
                return Err(ProjectCompileError::TypeLibraryMemberNotFound {
                    target: target_name,
                });
            }
            KnownTypeLibMemberResolution::Ambiguous => {
                return Err(ProjectCompileError::TypeLibraryMemberAmbiguous {
                    target: target_name,
                });
            }
        };
    if !matches!(
        member_spec.invoke_kind,
        TypeLibMemberInvokeKind::PropertyGet | TypeLibMemberInvokeKind::Method
    ) || !member_spec.parameter_names.is_empty()
    {
        return Ok(line.to_string());
    }
    Ok(format!(
        "{}{}{} = DispatchInvoke({}, {})",
        &line[..leading],
        if explicit_set {
            "Set "
        } else if explicit_let {
            "Let "
        } else {
            ""
        },
        lhs,
        var_name,
        member_token
    ))
}

fn rewrite_early_bound_object_assignment(
    manifest: &ProjectManifest,
    line: &str,
    early_bound: &BTreeMap<String, EarlyBoundBinding>,
) -> Result<String, ProjectCompileError> {
    if early_bound.is_empty() || class_state_line_is_non_executable(line) {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    if !trimmed[..trimmed.len().min(4)].eq_ignore_ascii_case("set ") {
        return Ok(line.to_string());
    }
    let payload = trimmed[4..].trim_start();
    let Some(eq_idx) = find_top_level_assignment_eq(payload) else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() {
        return Ok(line.to_string());
    }
    if !early_bound.contains_key(&normalize_identifier(lhs)) {
        return Ok(line.to_string());
    }
    let rewritten_rhs = rewrite_typelib_new_expression(manifest, rhs)?;
    if rewritten_rhs == rhs {
        return Ok(line.to_string());
    }
    Ok(format!(
        "{}Set {} = {}",
        &line[..leading],
        lhs,
        rewritten_rhs
    ))
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_member_dispatch(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let mut replacements: Vec<(usize, usize, String)> = Vec::new();
    let mut cursor = 0usize;
    while let Some(open_rel) = line[cursor..].find('(') {
        let open = cursor + open_rel;
        let Some((name_start, name_end)) = invocation_name_span(line, open) else {
            cursor = open + 1;
            continue;
        };
        let Some(close) = find_matching_paren(line, open) else {
            cursor = open + 1;
            continue;
        };
        let raw_name = line[name_start..name_end].trim();
        let (target, instance_arg) = if let Some(dot_idx) = raw_name.find('.') {
            let receiver = normalize_identifier(raw_name[..dot_idx].trim());
            let member = normalize_identifier(raw_name[dot_idx + 1..].trim());
            if receiver.is_empty() || member.is_empty() {
                cursor = close + 1;
                continue;
            }
            let Some((target, instance_arg)) = resolve_internal_class_member_target(
                &receiver,
                &member,
                raw_name,
                active_project,
                current_project,
                current_module,
                procedures,
                internal_class_bindings,
                shadowed_identifiers,
            )?
            else {
                cursor = close + 1;
                continue;
            };
            (target, instance_arg)
        } else {
            let receiver = normalize_identifier(raw_name);
            if receiver.is_empty() {
                cursor = close + 1;
                continue;
            }
            let Some((target, instance_arg)) =
                resolve_internal_class_default_member_target_of_kinds(
                    &receiver,
                    active_project,
                    current_project,
                    current_module,
                    procedures,
                    internal_class_bindings,
                    shadowed_identifiers,
                    &[ProcedureDeclKind::PropertyGet],
                )?
            else {
                cursor = close + 1;
                continue;
            };
            (target, instance_arg)
        };
        let args_raw = line[open + 1..close].trim();
        let args = split_top_level_args(args_raw)?;
        let mut rewritten_args = vec![instance_arg];
        rewritten_args.extend(args.into_iter().filter(|arg| !arg.trim().is_empty()));
        let replacement = format!("{target}({})", rewritten_args.join(", "));
        replacements.push((name_start, close + 1, replacement));
        cursor = close + 1;
    }
    let rewritten = if replacements.is_empty() {
        line.to_string()
    } else {
        let mut out = String::with_capacity(line.len() + 32);
        let mut previous = 0usize;
        for (start, end, replacement) in replacements {
            if start < previous || end > line.len() || start >= end {
                continue;
            }
            out.push_str(&line[previous..start]);
            out.push_str(&replacement);
            previous = end;
        }
        out.push_str(&line[previous..]);
        out
    };

    let rewritten = rewrite_internal_class_call_statement_without_parens(
        &rewritten,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
    )?;

    rewrite_internal_class_statement_invoke_without_parentheses(
        &rewritten,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
    )
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_property_reads(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    if (internal_class_bindings.is_empty() && !has_implicit_class_receivers(procedures))
        || class_state_line_is_non_executable(line)
    {
        return Ok(line.to_string());
    }
    let rewritten = rewrite_internal_class_property_expression_reads(
        line,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
    )?;
    rewrite_internal_class_default_member_statement_reads(
        &rewritten,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
    )
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_default_member_statement_reads(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    if trimmed.is_empty()
        || trimmed.contains(char::is_whitespace)
        || trimmed.contains('.')
        || trimmed.contains('=')
        || trimmed.contains('(')
        || trimmed.contains(')')
        || trimmed.contains(',')
    {
        return Ok(line.to_string());
    }
    let receiver = normalize_identifier(trimmed);
    if receiver.is_empty() {
        return Ok(line.to_string());
    }
    let Some((target, instance_arg)) = resolve_internal_class_default_member_target_of_kinds(
        &receiver,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
        &[ProcedureDeclKind::PropertyGet],
    )?
    else {
        return Ok(line.to_string());
    };
    Ok(format!("{}{}({})", &line[..leading], target, instance_arg))
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_property_expression_reads(
    text: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let bytes = text.as_bytes();
    let mut replacements: Vec<(usize, usize, String)> = Vec::new();
    let mut index = 0usize;
    while index < bytes.len() {
        if !is_identifier_byte(bytes[index]) || (index > 0 && is_identifier_byte(bytes[index - 1]))
        {
            index += 1;
            continue;
        }
        let receiver_start = index;
        while index < bytes.len() && is_identifier_byte(bytes[index]) {
            index += 1;
        }
        let receiver_end = index;
        if index >= bytes.len() || bytes[index] != b'.' {
            continue;
        }
        let member_start = index + 1;
        if member_start >= bytes.len() || !is_identifier_byte(bytes[member_start]) {
            continue;
        }
        index = member_start;
        while index < bytes.len() && is_identifier_byte(bytes[index]) {
            index += 1;
        }
        let member_end = index;
        let mut next = member_end;
        while next < bytes.len() && bytes[next].is_ascii_whitespace() {
            next += 1;
        }
        if text[..receiver_start].trim().is_empty()
            && next < bytes.len()
            && is_identifier_byte(bytes[next])
        {
            continue;
        }
        if next < bytes.len() && bytes[next] == b'(' {
            continue;
        }
        if next < bytes.len()
            && bytes[next] == b'='
            && property_expression_read_is_assignment_lhs(text, receiver_start)
        {
            continue;
        }
        let receiver = normalize_identifier(&text[receiver_start..receiver_end]);
        let member = normalize_identifier(&text[member_start..member_end]);
        if receiver.is_empty() || member.is_empty() {
            continue;
        }
        let raw_name = &text[receiver_start..member_end];
        if let Some((target, instance_arg)) = resolve_internal_class_member_target_of_kinds(
            &receiver,
            &member,
            raw_name,
            active_project,
            current_project,
            current_module,
            procedures,
            internal_class_bindings,
            shadowed_identifiers,
            &[ProcedureDeclKind::PropertyGet],
        )? {
            replacements.push((
                receiver_start,
                member_end,
                format!("{}({})", target, instance_arg),
            ));
        }
    }
    if replacements.is_empty() {
        return Ok(text.to_string());
    }
    let mut out = String::with_capacity(text.len() + 32);
    let mut previous = 0usize;
    for (start, end, replacement) in replacements {
        if start < previous || end > text.len() || start >= end {
            continue;
        }
        out.push_str(&text[previous..start]);
        out.push_str(&replacement);
        previous = end;
    }
    out.push_str(&text[previous..]);
    Ok(out)
}

fn is_identifier_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_'
}

fn property_expression_read_is_assignment_lhs(text: &str, receiver_start: usize) -> bool {
    let prefix = text[..receiver_start].trim();
    if prefix.is_empty() {
        return true;
    }

    matches!(prefix.to_ascii_lowercase().as_str(), "let" | "set")
}

#[allow(clippy::too_many_arguments)]
fn resolve_internal_class_member_target_of_kinds(
    receiver: &str,
    member: &str,
    raw_name: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
    allowed_kinds: &[ProcedureDeclKind],
) -> Result<Option<(String, String)>, ProjectCompileError> {
    let Some((target_project, target_module, instance_arg)) =
        (if let Some(binding) = internal_class_bindings.get(receiver) {
            Some((
                binding.project_name.clone(),
                binding.module_name.clone(),
                receiver.to_string(),
            ))
        } else {
            resolve_implicit_class_receiver_binding(receiver, procedures, shadowed_identifiers)?
        })
    else {
        return Ok(None);
    };

    let mut candidates = procedures
        .iter()
        .filter(|decl| {
            decl.project_name == target_project
                && decl.module_name == target_module
                && decl.procedure_name == member
                && (allowed_kinds.is_empty() || allowed_kinds.contains(&decl.kind))
                && is_visible_from_active_project(
                    decl,
                    active_project,
                    current_project,
                    current_module,
                )
        })
        .collect::<Vec<_>>();
    if candidates.is_empty() {
        return if allowed_kinds.is_empty() {
            Err(ProjectCompileError::NameResolutionNotFound {
                name: raw_name.to_string(),
            })
        } else {
            Ok(None)
        };
    }
    candidates.sort_by_key(|decl| decl.lowered_name.clone());
    Ok(Some((candidates[0].lowered_name.clone(), instance_arg)))
}

#[allow(clippy::too_many_arguments)]
fn resolve_internal_class_default_member_target_of_kinds(
    receiver: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
    allowed_kinds: &[ProcedureDeclKind],
) -> Result<Option<(String, String)>, ProjectCompileError> {
    let Some((target_project, target_module, instance_arg)) =
        (if let Some(binding) = internal_class_bindings.get(receiver) {
            Some((
                binding.project_name.clone(),
                binding.module_name.clone(),
                receiver.to_string(),
            ))
        } else {
            resolve_implicit_class_receiver_binding(receiver, procedures, shadowed_identifiers)?
        })
    else {
        return Ok(None);
    };

    let mut candidates = procedures
        .iter()
        .filter(|decl| {
            decl.project_name == target_project
                && decl.module_name == target_module
                && decl.is_default_member
                && (allowed_kinds.is_empty() || allowed_kinds.contains(&decl.kind))
                && is_visible_from_active_project(
                    decl,
                    active_project,
                    current_project,
                    current_module,
                )
        })
        .collect::<Vec<_>>();
    if candidates.is_empty() {
        candidates = procedures
            .iter()
            .filter(|decl| {
                decl.project_name == target_project
                    && decl.module_name == target_module
                    && (allowed_kinds.is_empty() || allowed_kinds.contains(&decl.kind))
                    && is_visible_from_active_project(
                        decl,
                        active_project,
                        current_project,
                        current_module,
                    )
            })
            .collect::<Vec<_>>();
        if candidates.is_empty() {
            return Err(ProjectCompileError::DefaultMemberResolutionMissing {
                name: receiver.to_string(),
            });
        }
        if candidates.len() != 1 {
            return Err(ProjectCompileError::DefaultMemberResolutionAmbiguous {
                name: receiver.to_string(),
            });
        }
    }
    candidates.sort_by_key(|decl| decl.lowered_name.clone());
    Ok(Some((candidates[0].lowered_name.clone(), instance_arg)))
}

#[allow(clippy::too_many_arguments)]
fn resolve_internal_class_member_target(
    receiver: &str,
    member: &str,
    raw_name: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<Option<(String, String)>, ProjectCompileError> {
    resolve_internal_class_member_target_of_kinds(
        receiver,
        member,
        raw_name,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
        &[],
    )
}
fn rewrite_internal_class_call_statement_without_parens(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("call ") {
        return Ok(line.to_string());
    }
    let payload = trimmed[5..].trim_start();
    if payload.is_empty() || payload.contains('(') {
        return Ok(line.to_string());
    }
    let callee_end = payload.find(char::is_whitespace).unwrap_or(payload.len());
    let callee = payload[..callee_end].trim();
    let args_tail = payload[callee_end..].trim();
    let (target, instance_arg) = if let Some(dot_idx) = callee.find('.') {
        let receiver = normalize_identifier(callee[..dot_idx].trim());
        let member = normalize_identifier(callee[dot_idx + 1..].trim());
        if receiver.is_empty() || member.is_empty() {
            return Ok(line.to_string());
        }
        let Some((target, instance_arg)) = resolve_internal_class_member_target(
            &receiver,
            &member,
            callee,
            active_project,
            current_project,
            current_module,
            procedures,
            internal_class_bindings,
            shadowed_identifiers,
        )?
        else {
            return Ok(line.to_string());
        };
        (target, instance_arg)
    } else {
        let receiver = normalize_identifier(callee);
        if receiver.is_empty() {
            return Ok(line.to_string());
        }
        let Some((target, instance_arg)) = resolve_internal_class_default_member_target_of_kinds(
            &receiver,
            active_project,
            current_project,
            current_module,
            procedures,
            internal_class_bindings,
            shadowed_identifiers,
            &[ProcedureDeclKind::PropertyGet],
        )?
        else {
            return Ok(line.to_string());
        };
        (target, instance_arg)
    };
    let joined_args = if args_tail.is_empty() {
        instance_arg
    } else {
        format!("{instance_arg}, {args_tail}")
    };
    Ok(format!(
        "{}Call {}({})",
        &line[..leading],
        target,
        joined_args
    ))
}
fn rewrite_internal_class_statement_invoke_without_parentheses(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if trimmed.is_empty()
        || lower.starts_with("call ")
        || trimmed.contains('(')
        || trimmed.contains('=')
    {
        return Ok(line.to_string());
    }
    let callee_end = trimmed.find(char::is_whitespace).unwrap_or(trimmed.len());
    if callee_end == trimmed.len() {
        return Ok(line.to_string());
    }
    let callee = trimmed[..callee_end].trim();
    let args_tail = trimmed[callee_end..].trim();
    if args_tail.is_empty() {
        return Ok(line.to_string());
    }
    let (target, instance_arg) = if let Some(dot_idx) = callee.find('.') {
        let receiver = normalize_identifier(callee[..dot_idx].trim());
        let member = normalize_identifier(callee[dot_idx + 1..].trim());
        if receiver.is_empty() || member.is_empty() {
            return Ok(line.to_string());
        }
        let Some((target, instance_arg)) = resolve_internal_class_member_target_of_kinds(
            &receiver,
            &member,
            callee,
            active_project,
            current_project,
            current_module,
            procedures,
            internal_class_bindings,
            shadowed_identifiers,
            &[ProcedureDeclKind::PropertyGet],
        )?
        else {
            return Ok(line.to_string());
        };
        (target, instance_arg)
    } else {
        let receiver = normalize_identifier(callee);
        if receiver.is_empty() {
            return Ok(line.to_string());
        }
        let Some((target, instance_arg)) = resolve_internal_class_default_member_target_of_kinds(
            &receiver,
            active_project,
            current_project,
            current_module,
            procedures,
            internal_class_bindings,
            shadowed_identifiers,
            &[ProcedureDeclKind::PropertyGet],
        )?
        else {
            return Ok(line.to_string());
        };
        (target, instance_arg)
    };
    Ok(format!(
        "{}{}({}, {})",
        &line[..leading],
        target,
        instance_arg,
        args_tail
    ))
}

fn class_module_self_targets(
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
) -> BTreeSet<String> {
    procedures
        .iter()
        .filter(|decl| {
            decl.project_name == current_project
                && decl.module_name == current_module
                && decl.module_kind == ModuleKind::Class
        })
        .map(|decl| decl.lowered_name.clone())
        .collect()
}

fn rewrite_internal_class_self_call_statement_without_parens(
    line: &str,
    self_targets: &BTreeSet<String>,
) -> String {
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("call ") {
        return line.to_string();
    }
    let payload = trimmed[5..].trim_start();
    if payload.is_empty() || payload.contains('(') {
        return line.to_string();
    }
    let callee_end = payload.find(char::is_whitespace).unwrap_or(payload.len());
    let callee = payload[..callee_end].trim();
    if callee.contains('.') {
        return line.to_string();
    }
    let callee_normalized = normalize_identifier(callee);
    if !self_targets.contains(&callee_normalized) {
        return line.to_string();
    }
    let args_tail = payload[callee_end..].trim();
    let joined_args = if args_tail.is_empty() {
        "__oxvba_this_instance".to_string()
    } else {
        format!("__oxvba_this_instance, {args_tail}")
    };
    format!("{}Call {}({})", &line[..leading], callee, joined_args)
}

fn rewrite_internal_class_self_dispatch(
    line: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
) -> Result<String, ProjectCompileError> {
    let self_targets = class_module_self_targets(current_project, current_module, procedures);
    if self_targets.is_empty() {
        return Ok(line.to_string());
    }

    let mut replacements: Vec<(usize, usize, String)> = Vec::new();
    let mut cursor = 0usize;
    while let Some(open_rel) = line[cursor..].find('(') {
        let open = cursor + open_rel;
        let Some((name_start, name_end)) = invocation_name_span(line, open) else {
            cursor = open + 1;
            continue;
        };
        let raw_name = line[name_start..name_end].trim();
        if raw_name.contains('.') {
            cursor = open + 1;
            continue;
        }
        let normalized = normalize_identifier(raw_name);
        if !self_targets.contains(&normalized) {
            cursor = open + 1;
            continue;
        }
        let Some(close) = find_matching_paren(line, open) else {
            cursor = open + 1;
            continue;
        };
        let args_raw = line[open + 1..close].trim();
        let args = split_top_level_args(args_raw)?;
        let mut rewritten_args = vec!["__oxvba_this_instance".to_string()];
        rewritten_args.extend(args.into_iter().filter(|arg| !arg.trim().is_empty()));
        let replacement = format!("{raw_name}({})", rewritten_args.join(", "));
        replacements.push((name_start, close + 1, replacement));
        cursor = close + 1;
    }

    let rewritten = if replacements.is_empty() {
        line.to_string()
    } else {
        let mut out = String::with_capacity(line.len() + 32);
        let mut previous = 0usize;
        for (start, end, replacement) in replacements {
            if start < previous || end > line.len() || start >= end {
                continue;
            }
            out.push_str(&line[previous..start]);
            out.push_str(&replacement);
            previous = end;
        }
        out.push_str(&line[previous..]);
        out
    };

    Ok(rewrite_internal_class_self_call_statement_without_parens(
        &rewritten,
        &self_targets,
    ))
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_set_assignment(
    manifest: &ProjectManifest,
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
    withevents_bindings: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("set ") {
        return Ok(line.to_string());
    }
    let payload = trimmed[4..].trim_start();
    let Some(eq_idx) = payload.find('=') else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() {
        return Ok(line.to_string());
    }
    if let Some(dot_idx) = lhs.find('.') {
        let receiver = normalize_identifier(lhs[..dot_idx].trim());
        let member_expr = lhs[dot_idx + 1..].trim();
        let (member, mut indexed_args) = if let Some(open_idx) = member_expr.find('(') {
            let Some(close_idx) = find_matching_paren(member_expr, open_idx) else {
                return Ok(line.to_string());
            };
            if close_idx != member_expr.len().saturating_sub(1) {
                return Ok(line.to_string());
            }
            let member_name = normalize_identifier(member_expr[..open_idx].trim());
            if member_name.is_empty() {
                return Ok(line.to_string());
            }
            let args_raw = member_expr[open_idx + 1..close_idx].trim();
            let args = split_top_level_args(args_raw)?
                .into_iter()
                .filter(|arg| !arg.trim().is_empty())
                .collect::<Vec<_>>();
            (member_name, args)
        } else {
            let member_name = normalize_identifier(member_expr);
            if member_name.is_empty() {
                return Ok(line.to_string());
            }
            (member_name, Vec::new())
        };
        if !receiver.is_empty()
            && let Some((target, instance_arg)) = resolve_internal_class_member_target_of_kinds(
                &receiver,
                &member,
                lhs,
                active_project,
                current_project,
                current_module,
                procedures,
                internal_class_bindings,
                shadowed_identifiers,
                &[ProcedureDeclKind::PropertySet],
            )?
        {
            let mut lowered_args = vec![instance_arg];
            lowered_args.append(&mut indexed_args);
            lowered_args.push(rhs.to_string());
            return Ok(format!(
                "{}{}({})",
                &line[..leading],
                target,
                lowered_args.join(", ")
            ));
        }
    }
    let (normalized_lhs, mut indexed_args) = if let Some(open_idx) = lhs.find('(') {
        let Some(close_idx) = find_matching_paren(lhs, open_idx) else {
            return Ok(line.to_string());
        };
        if close_idx != lhs.len().saturating_sub(1) {
            return Ok(line.to_string());
        }
        let receiver_name = normalize_identifier(lhs[..open_idx].trim());
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        let args_raw = lhs[open_idx + 1..close_idx].trim();
        let args = split_top_level_args(args_raw)?
            .into_iter()
            .filter(|arg| !arg.trim().is_empty())
            .collect::<Vec<_>>();
        (receiver_name, args)
    } else {
        let receiver_name = normalize_identifier(lhs);
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        (receiver_name, Vec::new())
    };
    if withevents_bindings.contains(&normalized_lhs) {
        let binding_token = withevents_binding_token(current_project, current_module, lhs);
        let rhs = rewrite_typelib_new_expression(manifest, rhs)?;
        return Ok(format!(
            "{}{} = __oxvba_withevents_set(__oxvba_this_instance, {}, {})",
            &line[..leading],
            lhs,
            binding_token,
            rhs
        ));
    }
    if !internal_class_bindings.contains_key(&normalized_lhs)
        && resolve_implicit_class_receiver_binding(
            &normalized_lhs,
            procedures,
            shadowed_identifiers,
        )?
        .is_none()
    {
        return Ok(line.to_string());
    }
    if indexed_args.is_empty()
        && internal_class_bindings.contains_key(&normalized_lhs)
        && (rhs.contains('.') || rhs.contains('('))
    {
        return Ok(line.to_string());
    }
    match resolve_internal_class_default_member_target_of_kinds(
        &normalized_lhs,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
        &[ProcedureDeclKind::PropertySet],
    ) {
        Ok(Some((target, instance_arg))) => {
            let mut lowered_args = vec![instance_arg];
            lowered_args.append(&mut indexed_args);
            lowered_args.push(rhs.to_string());
            return Ok(format!(
                "{}{}({})",
                &line[..leading],
                target,
                lowered_args.join(", ")
            ));
        }
        Ok(None) => {}
        Err(ProjectCompileError::DefaultMemberResolutionMissing { .. })
            if indexed_args.is_empty()
                && internal_class_bindings.contains_key(&normalized_lhs)
                && (rhs.contains('.') || rhs.contains('(')) =>
        {
            return Ok(line.to_string());
        }
        Err(err) => return Err(err),
    }
    Ok(format!("{}{} = {}", &line[..leading], lhs, rhs))
}

