#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_default_member_assignment(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    if (internal_class_bindings.is_empty() && !has_implicit_class_receivers(procedures))
        || class_state_line_is_non_executable(line)
    {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    if lowered.starts_with("set ") {
        return Ok(line.to_string());
    }
    let payload = if lowered.starts_with("let ") {
        trimmed[4..].trim_start()
    } else {
        trimmed
    };
    let Some(eq_idx) = payload.find('=') else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() || lhs.contains('.') {
        return Ok(line.to_string());
    }
    if rhs.starts_with("__oxvba_withevents_set(") {
        return Ok(line.to_string());
    }
    let (receiver, mut indexed_args) = if let Some(open_idx) = lhs.find('(') {
        let Some(close_idx) = find_matching_paren(lhs, open_idx) else {
            return Ok(line.to_string());
        };
        if close_idx != lhs.len().saturating_sub(1) {
            return Ok(line.to_string());
        }
        let receiver_name = normalize_identifier(lhs[..open_idx].trim());
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        let args_raw = lhs[open_idx + 1..close_idx].trim();
        let args = split_top_level_args(args_raw)?
            .into_iter()
            .filter(|arg| !arg.trim().is_empty())
            .collect::<Vec<_>>();
        (receiver_name, args)
    } else {
        let receiver_name = normalize_identifier(lhs);
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        (receiver_name, Vec::new())
    };
    if receiver.is_empty() {
        return Ok(line.to_string());
    }
    if let Some(binding) = internal_class_bindings.get(&receiver)
        && indexed_args.is_empty()
        && let Ok(instance_id) = rhs.parse::<i32>()
        && binding.generated_instance_id == Some(instance_id)
    {
        return Ok(line.to_string());
    }
    let Some((target, instance_arg)) = resolve_internal_class_default_member_target_of_kinds(
        &receiver,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
        &[ProcedureDeclKind::PropertyLet],
    )?
    else {
        return Ok(line.to_string());
    };
    let mut lowered_args = vec![instance_arg];
    lowered_args.append(&mut indexed_args);
    lowered_args.push(rhs.to_string());
    Ok(format!(
        "{}{}({})",
        &line[..leading],
        target,
        lowered_args.join(", ")
    ))
}

#[allow(clippy::too_many_arguments)]
fn rewrite_internal_class_default_member_read_assignment(
    line: &str,
    active_project: &str,
    current_project: &str,
    current_module: &str,
    procedures: &[ProcedureDecl],
    internal_class_bindings: &BTreeMap<String, InternalClassBinding>,
    shadowed_identifiers: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    if (internal_class_bindings.is_empty() && !has_implicit_class_receivers(procedures))
        || class_state_line_is_non_executable(line)
    {
        return Ok(line.to_string());
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    let explicit_set = lowered.starts_with("set ");
    let explicit_let = lowered.starts_with("let ");
    let payload = if explicit_set || explicit_let {
        trimmed[4..].trim_start()
    } else {
        trimmed
    };
    let Some(eq_idx) = payload.find('=') else {
        return Ok(line.to_string());
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() || lhs.contains('.') || rhs.contains('.') {
        return Ok(line.to_string());
    }
    let normalized_lhs = normalize_identifier(lhs);
    if procedures.iter().any(|procedure| {
        procedure.project_name.eq_ignore_ascii_case(current_project)
            && procedure.module_name.eq_ignore_ascii_case(current_module)
            && normalize_identifier(&procedure.procedure_name) == normalized_lhs
            && procedure.kind.has_return_value()
    }) {
        return Ok(line.to_string());
    }
    let (rhs_name, indexed_args) = if let Some(open_idx) = rhs.find('(') {
        let Some(close_idx) = find_matching_paren(rhs, open_idx) else {
            return Ok(line.to_string());
        };
        if close_idx != rhs.len().saturating_sub(1) {
            return Ok(line.to_string());
        }
        let receiver_name = normalize_identifier(rhs[..open_idx].trim());
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        let args_raw = rhs[open_idx + 1..close_idx].trim();
        let args = split_top_level_args(args_raw)?
            .into_iter()
            .filter(|arg| !arg.trim().is_empty())
            .collect::<Vec<_>>();
        (receiver_name, args)
    } else {
        let receiver_name = normalize_identifier(rhs);
        if receiver_name.is_empty() {
            return Ok(line.to_string());
        }
        (receiver_name, Vec::new())
    };
    if rhs_name.is_empty() {
        return Ok(line.to_string());
    }
    let resolved_target = resolve_internal_class_default_member_target_of_kinds(
        &rhs_name,
        active_project,
        current_project,
        current_module,
        procedures,
        internal_class_bindings,
        shadowed_identifiers,
        &[ProcedureDeclKind::PropertyGet],
    )?;
    let Some((target, instance_arg)) = resolved_target else {
        return Ok(line.to_string());
    };
    let mut lowered_args = vec![instance_arg];
    lowered_args.extend(indexed_args);
    Ok(format!(
        "{}{}{} = {}({})",
        &line[..leading],
        if explicit_set {
            "Set "
        } else if explicit_let {
            "Let "
        } else {
            ""
        },
        lhs,
        target,
        lowered_args.join(", ")
    ))
}
fn collect_module_state_bindings(
    module: &ModuleUnit,
    current_project: &str,
    current_module: &str,
) -> ModuleStateBindings {
    let owner_expr = match module.module_kind {
        ModuleKind::Class => "__oxvba_this_instance".to_string(),
        ModuleKind::Procedural => {
            procedural_module_state_owner_token(current_project, current_module).to_string()
        }
        _ => {
            return ModuleStateBindings {
                owner_expr: String::new(),
                field_tokens: BTreeMap::new(),
            };
        }
    };

    let mut field_tokens = BTreeMap::new();
    let mut in_procedure = false;
    for line in module.source.lines() {
        let normalized = normalize_visibility_prefixed_procedure_signature(line);
        if parse_procedure_signature_line(&normalized).is_some() {
            in_procedure = true;
            continue;
        }
        let lower = line.trim().to_ascii_lowercase();
        if lower == "end sub" || lower == "end function" || lower == "end property" {
            in_procedure = false;
            continue;
        }
        if in_procedure {
            continue;
        }
        for field_name in parse_class_state_field_names(line) {
            field_tokens.insert(
                normalize_identifier(&field_name),
                class_state_binding_token(current_project, current_module, &field_name),
            );
        }
    }
    ModuleStateBindings {
        owner_expr,
        field_tokens,
    }
}

fn collect_internal_class_imported_collection_newenum_fields(
    module: &ModuleUnit,
) -> BTreeSet<String> {
    let mut fields = BTreeSet::new();
    if module.module_kind != ModuleKind::Class {
        return fields;
    }
    for line in module.source.lines() {
        let trimmed = line.trim_start();
        let lowered = trimmed.to_ascii_lowercase();
        if !lowered.starts_with("set ") {
            continue;
        }
        let payload = trimmed[4..].trim_start();
        let Some(eq_idx) = find_top_level_assignment_eq(payload) else {
            continue;
        };
        let lhs = payload[..eq_idx].trim();
        if normalize_identifier(lhs) != "newenum" {
            continue;
        }
        let rhs = payload[eq_idx + 1..].trim();
        let Some(dot_idx) = rhs.find('.') else {
            continue;
        };
        let receiver = normalize_identifier(rhs[..dot_idx].trim());
        let member_expr = rhs[dot_idx + 1..].trim();
        if receiver.is_empty() {
            continue;
        }
        if member_expr.eq_ignore_ascii_case("[_newenum]")
            || member_expr.eq_ignore_ascii_case("_newenum")
        {
            fields.insert(receiver);
        }
    }
    fields
}

fn parse_class_state_field_names(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    let lower = trimmed.to_ascii_lowercase();
    let payload = if lower.starts_with("private ") {
        &trimmed[8..]
    } else if lower.starts_with("public ") {
        &trimmed[7..]
    } else if lower.starts_with("dim ") {
        &trimmed[4..]
    } else {
        return Vec::new();
    };
    let payload_lower = payload.trim_start().to_ascii_lowercase();
    if payload_lower.starts_with("withevents ")
        || payload_lower.starts_with("sub ")
        || payload_lower.starts_with("function ")
        || payload_lower.starts_with("property ")
        || payload_lower.starts_with("event ")
        || payload_lower.starts_with("declare ")
        || payload_lower.starts_with("const ")
    {
        return Vec::new();
    }
    payload
        .split(',')
        .filter_map(|part| {
            let token = part
                .trim()
                .split(|ch: char| ch.is_ascii_whitespace() || ch == '(')
                .next()
                .unwrap_or_default();
            normalize_procedure_name(token)
        })
        .collect()
}

fn parse_module_scope_typed_declaration_types(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    let lower = trimmed.to_ascii_lowercase();
    let payload = if lower.starts_with("private ") {
        &trimmed[8..]
    } else if lower.starts_with("public ") {
        &trimmed[7..]
    } else if lower.starts_with("dim ") {
        &trimmed[4..]
    } else {
        return Vec::new();
    };
    let payload_lower = payload.trim_start().to_ascii_lowercase();
    if payload_lower.starts_with("withevents ")
        || payload_lower.starts_with("sub ")
        || payload_lower.starts_with("function ")
        || payload_lower.starts_with("property ")
        || payload_lower.starts_with("event ")
        || payload_lower.starts_with("declare ")
        || payload_lower.starts_with("const ")
    {
        return Vec::new();
    }
    payload
        .split(',')
        .filter_map(|part| {
            let (_, rhs) = split_keyword_ascii_ci(part.trim(), " as ")?;
            let mut type_text = rhs.trim();
            if type_text.len() >= 4 && type_text[..4].eq_ignore_ascii_case("new ") {
                type_text = type_text[4..].trim();
            }
            let token = type_text
                .split(|ch: char| ch.is_ascii_whitespace() || ch == '(')
                .next()
                .unwrap_or_default()
                .trim();
            if token.is_empty() {
                return None;
            }
            Some(token.to_string())
        })
        .collect()
}

fn parse_procedure_signature_type_references(line: &str) -> Vec<String> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    let lower = trimmed.to_ascii_lowercase();
    let tail = if lower.starts_with("public ") {
        trimmed[7..].trim()
    } else if lower.starts_with("private ") {
        trimmed[8..].trim()
    } else {
        trimmed
    };
    let lower_tail = tail.to_ascii_lowercase();
    let remainder = if lower_tail.starts_with("sub ") {
        tail[4..].trim()
    } else if lower_tail.starts_with("function ") {
        tail[9..].trim()
    } else if lower_tail.starts_with("property get ")
        || lower_tail.starts_with("property let ")
        || lower_tail.starts_with("property set ")
    {
        tail[13..].trim()
    } else {
        return Vec::new();
    };

    let mut out = Vec::new();
    if let Some(open_idx) = remainder.find('(') {
        let Some(close_idx) = find_matching_paren(remainder, open_idx) else {
            return Vec::new();
        };
        let payload = remainder[open_idx + 1..close_idx].trim();
        if let Ok(params) = split_top_level_args(payload) {
            for param in params {
                if let Some((_, rhs)) = split_keyword_ascii_ci(param.trim(), " as ")
                    && let Some(type_name) = extract_signature_type_name(rhs)
                {
                    out.push(type_name);
                }
            }
        }
        if let Some(type_name) =
            extract_signature_return_type_name(remainder[close_idx + 1..].trim())
        {
            out.push(type_name);
        }
        return out;
    }

    if let Some(type_name) = extract_signature_return_type_name(remainder) {
        out.push(type_name);
    }
    out
}

fn extract_signature_type_name(type_text: &str) -> Option<String> {
    let mut type_text = type_text.trim();
    if type_text.is_empty() {
        return None;
    }
    if let Some((lhs, _)) = type_text.split_once('=') {
        type_text = lhs.trim();
    }
    if type_text.len() >= 4 && type_text[..4].eq_ignore_ascii_case("new ") {
        type_text = type_text[4..].trim();
    }
    let token = type_text
        .split(|ch: char| ch.is_ascii_whitespace() || ch == '(' || ch == '=')
        .next()
        .unwrap_or_default()
        .trim();
    if token.is_empty() {
        None
    } else {
        Some(token.to_string())
    }
}

fn extract_signature_return_type_name(text: &str) -> Option<String> {
    let trimmed = text.trim();
    if trimmed.len() >= 3 && trimmed[..3].eq_ignore_ascii_case("as ") {
        return extract_signature_type_name(trimmed[3..].trim());
    }
    let (_, rhs) = split_keyword_ascii_ci(trimmed, " as ")?;
    extract_signature_type_name(rhs)
}

fn rewrite_internal_class_state_assignment(
    line: &str,
    module_state_bindings: &ModuleStateBindings,
) -> String {
    if module_state_bindings.field_tokens.is_empty() || class_state_line_is_non_executable(line) {
        return line.to_string();
    }
    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let Some(eq_idx) = trimmed.find('=') else {
        return line.to_string();
    };
    let lhs = trimmed[..eq_idx].trim();
    let rhs = trimmed[eq_idx + 1..].trim();
    if lhs.is_empty() || rhs.is_empty() {
        return line.to_string();
    }
    let normalized_lhs = normalize_identifier(lhs);
    let Some(binding_token) = module_state_bindings
        .field_tokens
        .get(&normalized_lhs)
        .copied()
    else {
        return line.to_string();
    };
    let rewritten_rhs = rewrite_internal_class_state_expression_reads(rhs, module_state_bindings);
    format!(
        "{}{} = __oxvba_withevents_set({}, {}, {})",
        &line[..leading],
        lhs,
        module_state_bindings.owner_expr,
        binding_token,
        rewritten_rhs
    )
}

fn rewrite_internal_class_collection_member_calls(
    line: &str,
    module_state_bindings: &ModuleStateBindings,
    imported_collection_newenum_fields: &BTreeSet<String>,
) -> Result<String, ProjectCompileError> {
    if module_state_bindings.field_tokens.is_empty()
        || imported_collection_newenum_fields.is_empty()
        || class_state_line_is_non_executable(line)
    {
        return Ok(line.to_string());
    }

    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    let payload = if lowered.starts_with("call ") {
        trimmed[5..].trim_start()
    } else {
        trimmed
    };
    if payload.contains('=') {
        return Ok(line.to_string());
    }

    let Some(dot_idx) = payload.find('.') else {
        return Ok(line.to_string());
    };
    let receiver = payload[..dot_idx].trim();
    let normalized_receiver = normalize_identifier(receiver);
    if !imported_collection_newenum_fields.contains(&normalized_receiver) {
        return Ok(line.to_string());
    }
    let Some(binding_token) = module_state_bindings
        .field_tokens
        .get(&normalized_receiver)
        .copied()
    else {
        return Ok(line.to_string());
    };
    let member_expr = payload[dot_idx + 1..].trim();
    if member_expr.is_empty() {
        return Ok(line.to_string());
    }

    let (member_name, args) = if let Some(open_idx) = member_expr.find('(') {
        let Some(close_idx) = find_matching_paren(member_expr, open_idx) else {
            return Ok(line.to_string());
        };
        if close_idx != member_expr.len().saturating_sub(1) {
            return Ok(line.to_string());
        }
        let member_name = normalize_identifier(member_expr[..open_idx].trim());
        let args = split_top_level_args(member_expr[open_idx + 1..close_idx].trim())?;
        (member_name, args)
    } else {
        let Some(space_idx) = member_expr.find(char::is_whitespace) else {
            return Ok(line.to_string());
        };
        let member_name = normalize_identifier(member_expr[..space_idx].trim());
        let args = split_top_level_args(member_expr[space_idx..].trim())?;
        (member_name, args)
    };

    if !member_name.eq_ignore_ascii_case("add") {
        return Ok(line.to_string());
    }
    let args = args
        .into_iter()
        .filter(|arg| !arg.trim().is_empty())
        .collect::<Vec<_>>();
    if args.len() != 1 {
        return Ok(line.to_string());
    }

    Ok(format!(
        "{}{} = __oxvba_array_append(__oxvba_withevents_get({}, {}), {})",
        &line[..leading],
        receiver,
        module_state_bindings.owner_expr,
        binding_token,
        args[0].trim()
    ))
}

fn rewrite_internal_class_collection_newenum_read_assignment(
    line: &str,
    module_state_bindings: &ModuleStateBindings,
    imported_collection_newenum_fields: &BTreeSet<String>,
) -> String {
    if module_state_bindings.field_tokens.is_empty()
        || imported_collection_newenum_fields.is_empty()
        || class_state_line_is_non_executable(line)
    {
        return line.to_string();
    }

    let trimmed = line.trim_start();
    let leading = line.len().saturating_sub(trimmed.len());
    let lowered = trimmed.to_ascii_lowercase();
    if !lowered.starts_with("set ") {
        return line.to_string();
    }

    let payload = trimmed[4..].trim_start();
    let Some(eq_idx) = find_top_level_assignment_eq(payload) else {
        return line.to_string();
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    if normalize_identifier(lhs) != "newenum" {
        return line.to_string();
    }

    let Some(dot_idx) = rhs.find('.') else {
        return line.to_string();
    };
    let receiver = rhs[..dot_idx].trim();
    let normalized_receiver = normalize_identifier(receiver);
    if !imported_collection_newenum_fields.contains(&normalized_receiver) {
        return line.to_string();
    }
    let Some(binding_token) = module_state_bindings
        .field_tokens
        .get(&normalized_receiver)
        .copied()
    else {
        return line.to_string();
    };
    let member_expr = rhs[dot_idx + 1..].trim();
    if !(member_expr.eq_ignore_ascii_case("[_newenum]")
        || member_expr.eq_ignore_ascii_case("_newenum"))
    {
        return line.to_string();
    }

    format!(
        "{}{} = __oxvba_withevents_get({}, {})",
        &line[..leading],
        lhs,
        module_state_bindings.owner_expr,
        binding_token
    )
}

fn rewrite_internal_class_imported_collection_activation(
    line: &str,
    module_state_bindings: &ModuleStateBindings,
    imported_collection_newenum_fields: &BTreeSet<String>,
) -> String {
    if module_state_bindings.field_tokens.is_empty()
        || imported_collection_newenum_fields.is_empty()
    {
        return line.to_string();
    }

    let trimmed = line.trim_start();
    let lowered = trimmed.to_ascii_lowercase();
    if !lowered.starts_with("set ") {
        return line.to_string();
    }

    let payload = trimmed[4..].trim_start();
    let Some(eq_idx) = find_top_level_assignment_eq(payload) else {
        return line.to_string();
    };
    let lhs = payload[..eq_idx].trim();
    let rhs = payload[eq_idx + 1..].trim();
    let normalized_lhs = normalize_identifier(lhs);
    if !imported_collection_newenum_fields.contains(&normalized_lhs)
        || !module_state_bindings
            .field_tokens
            .contains_key(&normalized_lhs)
        || !rhs
            .trim_start()
            .to_ascii_lowercase()
            .starts_with("createobject(")
    {
        return line.to_string();
    }

    String::new()
}

fn rewrite_internal_class_state_reads(
    line: &str,
    module_state_bindings: &ModuleStateBindings,
) -> String {
    if module_state_bindings.field_tokens.is_empty() || class_state_line_is_non_executable(line) {
        return line.to_string();
    }
    rewrite_internal_class_state_expression_reads(line, module_state_bindings)
}

fn rewrite_internal_class_state_expression_reads(
    text: &str,
    module_state_bindings: &ModuleStateBindings,
) -> String {
    let mut rewritten = text.to_string();
    for (field_name, binding_token) in &module_state_bindings.field_tokens {
        let replacement = format!(
            "__oxvba_withevents_get({}, {})",
            module_state_bindings.owner_expr, binding_token
        );
        rewritten = rewrite_bare_identifier(&rewritten, field_name, &replacement);
    }
    rewritten
}

fn class_state_line_is_non_executable(line: &str) -> bool {
    let trimmed = line.trim_start();
    if trimmed.is_empty() {
        return true;
    }
    let lower = trimmed.to_ascii_lowercase();
    lower.starts_with("attribute ")
        || lower.starts_with("option ")
        || lower.starts_with("implements ")
        || lower.starts_with("public ")
        || lower.starts_with("private ")
        || lower.starts_with("dim ")
        || lower.starts_with("const ")
        || lower.starts_with("event ")
        || lower.starts_with("declare ")
        || lower.starts_with("sub ")
        || lower.starts_with("function ")
        || lower.starts_with("property ")
        || lower.starts_with("end ")
}

fn class_state_binding_token(project: &str, module: &str, field_name: &str) -> i32 {
    let mut hash: u32 = 2_166_136_261;
    let key = format!(
        "field|{}|{}|{}",
        normalize_identifier(project),
        normalize_identifier(module),
        normalize_identifier(field_name)
    );
    for byte in key.bytes() {
        hash ^= byte as u32;
        hash = hash.wrapping_mul(16_777_619);
    }
    let signed = (hash & 0x7fff_ffff) as i32;
    if signed == 0 { 1 } else { signed }
}

fn procedural_module_state_owner_token(project: &str, module: &str) -> i32 {
    let mut hash: u32 = 2_166_136_261;
    let key = format!(
        "module-state|{}|{}",
        normalize_identifier(project),
        normalize_identifier(module)
    );
    for byte in key.bytes() {
        hash ^= byte as u32;
        hash = hash.wrapping_mul(16_777_619);
    }
    let signed = (hash & 0x7fff_ffff) as i32;
    if signed == 0 { 1 } else { signed }
}

fn withevents_binding_token(project: &str, module: &str, var_name: &str) -> i32 {
    let mut hash: u32 = 2_166_136_261;
    let key = format!(
        "{}|{}|{}",
        normalize_identifier(project),
        normalize_identifier(module),
        normalize_identifier(var_name)
    );
    for byte in key.bytes() {
        hash ^= byte as u32;
        hash = hash.wrapping_mul(16_777_619);
    }
    let token = (hash & 0x7fff_ffff) as i32;
    if token == 0 { 1 } else { token }
}

fn split_top_level_args(args: &str) -> Result<Vec<String>, ProjectCompileError> {
    if args.trim().is_empty() {
        return Ok(Vec::new());
    }
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut in_string = false;
    let chars = args.as_bytes();
    let mut idx = 0usize;
    while idx < chars.len() {
        let ch = chars[idx] as char;
        if ch == '"' {
            in_string = !in_string;
            idx += 1;
            continue;
        }
        if in_string {
            idx += 1;
            continue;
        }
        match ch {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                out.push(args[start..idx].trim().to_string());
                start = idx + 1;
            }
            _ => {}
        }
        idx += 1;
    }
    if depth != 0 || in_string {
        return Err(ProjectCompileError::BackendCompile {
            message: "BIND-E-TYPELIB-ARG-PARSE: malformed argument list while rewriting early-bound member invocation".to_string(),
        });
    }
    out.push(args[start..].trim().to_string());
    Ok(out)
}

fn find_top_level_assignment_eq(text: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut idx = 0usize;
    while idx < bytes.len() {
        let ch = bytes[idx] as char;
        if ch == '"' {
            in_string = !in_string;
            idx += 1;
            continue;
        }
        if in_string {
            idx += 1;
            continue;
        }
        match ch {
            '(' => depth += 1,
            ')' => depth -= 1,
            '=' if depth == 0 => {
                if idx > 0 && bytes[idx - 1] == b':' {
                    idx += 1;
                    continue;
                }
                return Some(idx);
            }
            _ => {}
        }
        idx += 1;
    }
    None
}

fn find_matching_paren(text: &str, open_idx: usize) -> Option<usize> {
    let bytes = text.as_bytes();
    if open_idx >= bytes.len() || bytes[open_idx] != b'(' {
        return None;
    }
    let mut depth = 0i32;
    let mut in_string = false;
    for (idx, b) in bytes.iter().enumerate().skip(open_idx) {
        let ch = *b as char;
        if ch == '"' {
            in_string = !in_string;
            continue;
        }
        if in_string {
            continue;
        }
        match ch {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return Some(idx);
                }
                if depth < 0 {
                    return None;
                }
            }
            _ => {}
        }
    }
    None
}

fn split_keyword_ascii_ci<'a>(text: &'a str, keyword: &'a str) -> Option<(&'a str, &'a str)> {
    let lower = text.to_ascii_lowercase();
    let needle = keyword.to_ascii_lowercase();
    let idx = lower.find(&needle)?;
    Some((&text[..idx], &text[idx + keyword.len()..]))
}

