    #[test]
    fn compile_project_library_emits_exportable_dynamic_routes_for_exposed_creatable_class() {
        let mut widget = module_unit_from_source(
            "Widget",
            ModuleKind::Class,
            concat!(
                "Attribute VB_Name = \"Widget\"\n",
                "Public Property Get Value() As Long\n",
                "Value = 42\n",
                "End Property\n",
                "Attribute Value.VB_UserMemId = 0\n",
                "Public Property Get NewEnum() As Long\n",
                "NewEnum = 42\n",
                "End Property\n",
                "Attribute NewEnum.VB_UserMemId = -4\n",
                "Attribute NewEnum.VB_MemberFlags = \"40\"\n"
            ),
        )
        .expect("widget module parses");
        widget.attributes.vb_creatable = true;
        widget.attributes.vb_exposed = true;

        let manifest = ProjectManifest {
            project_name: "AttrExport".to_string(),
            project_kind: ProjectKind::Library,
            modules: vec![widget],
            references: Vec::new(),
            reference_projects: Vec::new(),
            conditional_constants: BTreeMap::new(),
        };

        let compiled =
            compile_project(&manifest).expect("library export route inventory should compile");
        let route = compiled
            .project_dynamic_objects
            .iter()
            .find(|route| route.module_name.eq_ignore_ascii_case("Widget"))
            .expect("exportable class route should exist");
        let value = route
            .members
            .iter()
            .find(|member| member.member_name.eq_ignore_ascii_case("Value"))
            .expect("default member should be exported");
        assert_eq!(value.dispatch_id, Some(0));
        assert!(value.is_default_member);

        let new_enum = route
            .members
            .iter()
            .find(|member| member.member_name.eq_ignore_ascii_case("NewEnum"))
            .expect("newenum member should be exported");
        assert_eq!(new_enum.dispatch_id, Some(-4));
        assert_eq!(new_enum.member_flags, Some(0x40));
    }

    #[test]
    fn expand_bound_source_line_stores_imported_typelib_metadata_in_early_bound_binding() {
        let manifest = ProjectManifest {
            project_name: "ProjectA".to_string(),
            project_kind: ProjectKind::Source,
            modules: Vec::new(),
            references: vec![ProjectReference {
                referenced_project_name: "OxVba".to_string(),
                reference_kind: ReferenceKind::TypeLibrary,
            }],
            reference_projects: Vec::new(),
            conditional_constants: BTreeMap::new(),
        };
        let mut early_bound = BTreeMap::new();
        let mut internal_class_bindings = BTreeMap::new();
        let mut withevents_bindings = BTreeSet::new();
        let mut next_internal_instance_id = 1;
        let mut dynamic_instance_bindings = Vec::new();
        let expanded = expand_bound_source_line(
            "Dim obj As New OxVba.TestDispatch",
            &manifest,
            "projecta",
            &BTreeMap::new(),
            &[],
            &mut early_bound,
            &mut internal_class_bindings,
            &mut withevents_bindings,
            &mut next_internal_instance_id,
            &mut dynamic_instance_bindings,
        )
        .expect("external dim should bind through metadata");

        assert_eq!(
            expanded,
            vec![
                "Dim obj As Object".to_string(),
                "Set obj = CreateObject(\"OxVba.TestDispatch\")".to_string()
            ]
        );
        let binding = early_bound.get("obj").expect("binding should be recorded");
        assert_eq!(binding.qualified_type, "OxVba.TestDispatch");
        let metadata = binding
            .typelib_metadata
            .as_ref()
            .expect("supported imported binding should carry metadata");
        assert_eq!(
            metadata.activation_prog_id.as_deref(),
            Some("OxVba.TestDispatch")
        );
        assert!(
            metadata
                .members
                .iter()
                .any(|member| member.name == "EchoVariant" && member.is_default_member),
            "expected imported binding metadata to carry authoritative default-member identity"
        );
    }

